import time
START = time.time()
DEADLINE = START + 80.0
import json
import math
import random
import itertools
import numpy as np
from numba import njit

rng = random.Random(1001)
INCUMBENT = (0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056)

@njit
def extension_valid(a, x):
    n = len(a)
    for i in range(n):
        if a[i] == x:
            return False
    d = np.empty(6, dtype=np.int64)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                d[0] = abs(a[i] - a[j])
                d[1] = abs(a[i] - a[k])
                d[2] = abs(a[j] - a[k])
                d[3] = abs(a[i] - x)
                d[4] = abs(a[j] - x)
                d[5] = abs(a[k] - x)
                distinct = 0
                for p in range(6):
                    fresh = True
                    for q in range(p):
                        if d[p] == d[q]:
                            fresh = False
                            break
                    if fresh:
                        distinct += 1
                if distinct < 5:
                    return False
    return True

@njit
def exact_h(a):
    # Each sum collision gives a forbidden vertex mask. A subset is
    # Sidon exactly when it contains none of these masks.
    n = len(a)
    m = n * (n + 1) // 2
    sums = np.empty(m, dtype=np.int64)
    masks = np.empty(m, dtype=np.int64)
    t = 0
    for i in range(n):
        for j in range(i, n):
            sums[t] = a[i] + a[j]
            masks[t] = (1 << i) | (1 << j)
            t += 1
    # At most m*(m-1)/2 collision pairs, so this allocation is safe
    # even without relying on the (4,5) hypothesis.
    tails = np.empty((n, m * (m - 1) // 2 + 1), dtype=np.int64)
    counts = np.zeros(n, dtype=np.int64)
    edges = 0
    for p in range(m):
        for q in range(p):
            if sums[p] == sums[q]:
                mask = masks[p] | masks[q]
                b = 0
                temp = mask
                while temp > 1:
                    b += 1
                    temp >>= 1
                tail = mask ^ (1 << b)
                duplicate = False
                for z in range(counts[b]):
                    if tails[b, z] == tail:
                        duplicate = True
                        break
                if not duplicate:
                    tails[b, counts[b]] = tail
                    counts[b] += 1
                    edges += 1
    size = 1 << n
    valid = np.zeros(size, dtype=np.uint8)
    cardinality = np.zeros(size, dtype=np.uint8)
    valid[0] = 1
    best = 0
    b = 0
    bit = 1
    for mask in range(1, size):
        if mask == bit * 2:
            bit *= 2
            b += 1
        rest = mask ^ bit
        if valid[rest] == 0:
            continue
        good = True
        for z in range(counts[b]):
            tail = tails[b, z]
            if (rest & tail) == tail:
                good = False
                break
        if good:
            valid[mask] = 1
            cardinality[mask] = cardinality[rest] + 1
            if cardinality[mask] > best:
                best = cardinality[mask]
    return best, edges

@njit
def evaluate_extensions(parent, candidates):
    n = len(parent)
    hs = np.zeros(len(candidates), dtype=np.int64)
    es = np.zeros(len(candidates), dtype=np.int64)
    child = np.empty(n + 1, dtype=np.int64)
    for i in range(n):
        child[i] = parent[i]
    for p in range(len(candidates)):
        x = candidates[p]
        if extension_valid(parent, x):
            child[n] = x
            h, e = exact_h(child)
            hs[p] = h
            es[p] = e
    return hs, es

def canonical(values):
    a = sorted(values)
    lo = a[0]
    a = [x - lo for x in a]
    g = 0
    for x in a:
        g = math.gcd(g, x)
    if g > 1:
        a = [x // g for x in a]
    forward = tuple(a)
    reverse = tuple(a[-1] - x for x in reversed(a))
    return min(forward, reverse)

def official_verify(elements):
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        raise ValueError('size')
    if any(type(x) is not int or abs(x) > 1000000000 for x in elements):
        raise ValueError('type or bounds')
    if len(set(elements)) != len(elements):
        raise ValueError('duplicates')
    a = sorted(elements)
    for four in itertools.combinations(a, 4):
        ds = {four[j] - four[i] for i in range(4) for j in range(i + 1, 4)}
        if len(ds) < 5:
            raise ValueError('(4,5) failure')
    for k in range(len(a), 0, -1):
        for sub in itertools.combinations(a, k):
            sums = set()
            good = True
            for i, x in enumerate(sub):
                for y in sub[i:]:
                    s = x + y
                    if s in sums:
                        good = False
                        break
                    sums.add(s)
                if not good:
                    break
            if good:
                return k
    raise ValueError('no Sidon subset')

fallback = [0, 1, 2, 5]
best = tuple(fallback)
best_h = official_verify(fallback)
best_edges = 0
archive = [(best_h / len(best), best_h, best)]

# Compilation is charged against the same wall-clock deadline.
evaluate_extensions(np.array([0, 1, 2], dtype=np.int64), np.array([5], dtype=np.int64))

restarts = 0
while time.time() < DEADLINE:
    restarts += 1
    width = rng.choice([10, 14, 18, 22])
    # No incumbent coordinates are used: all roots are independent seeds.
    seeds = {(0, 1, 2)}
    while len(seeds) < width:
        span = rng.choice([12, 24, 48, 96, 192])
        seeds.add(canonical(rng.sample(range(span + 1), 3)))
    beam = list(seeds)
    rng.shuffle(beam)
    temperature = rng.uniform(0.18, 0.52)
    edge_weight = rng.uniform(0.025, 0.095)
    for target_n in range(4, 14):
        if time.time() >= DEADLINE:
            break
        pool = {}
        for parent_id, a in enumerate(beam):
            if time.time() >= DEADLINE:
                break
            values = set(a)
            proposals = set()
            for i, x in enumerate(a):
                for y in a[i + 1:]:
                    proposals.add(2 * x - y)
                    proposals.add(2 * y - x)
                    if (x + y) % 2 == 0:
                        proposals.add((x + y) // 2)
            # A few unconstrained additions allow later AP-rich growth.
            span = max(8, a[-1])
            for _ in range(12 if target_n < 9 else 5):
                proposals.add(rng.randint(-span // 2, span + span // 2))
            proposals.difference_update(values)
            candidates = sorted(x for x in proposals if abs(x) <= 100000000)
            if not candidates:
                continue
            hs, es = evaluate_extensions(np.array(a, dtype=np.int64), np.array(candidates, dtype=np.int64))
            for x, hh, ee in zip(candidates, hs, es):
                h = int(hh)
                if h == 0:
                    continue
                e = int(ee)
                child = canonical(a + (x,))
                if child[-1] > 1000000000 or child in pool:
                    continue
                pool[child] = (h, e, parent_id)
                improve = h * len(best) < best_h * target_n
                tie = h * len(best) == best_h * target_n
                if improve or (tie and (target_n > len(best) or (target_n == len(best) and e > best_edges))):
                    best, best_h, best_edges = child, h, e
                    archive.append((h / target_n, h, child))
        if not pool:
            break
        # Gumbel perturbations preserve exploration without ignoring exact h.
        ranked = []
        for a, (h, e, parent_id) in pool.items():
            u = max(1e-12, rng.random())
            gumbel = -math.log(-math.log(u))
            key = h - edge_weight * e - temperature * gumbel
            ranked.append((key, a, parent_id))
        ranked.sort()
        selected = []
        parent_counts = {}
        deferred = []
        cap = max(3, width // 3)
        for key, a, parent_id in ranked:
            if parent_counts.get(parent_id, 0) >= cap:
                deferred.append(a)
                continue
            selected.append(a)
            parent_counts[parent_id] = parent_counts.get(parent_id, 0) + 1
            if len(selected) == width:
                break
        if len(selected) < width:
            selected.extend(deferred[:width - len(selected)])
        beam = selected

# Independent, literal exhaustive verification; never trust only the fast DP.
# All searched sets have at most 13 elements, leaving ample verification time.
choices = [(best_h / len(best), best_h, best)] + sorted(archive, key=lambda z: (z[0], -len(z[2])))
answer = fallback
seen = set()
for score, claimed_h, candidate in choices:
    if candidate in seen or tuple(sorted(candidate)) == INCUMBENT:
        continue
    seen.add(candidate)
    trial = [int(x) for x in candidate]
    try:
        actual_h = official_verify(trial)
    except ValueError:
        continue
    if actual_h == claimed_h:
        answer = trial
        break
# The fallback was independently verified before searching as well.
print(json.dumps({'elements': answer}))

import time
START = time.time()
DEADLINE = START + 80.0
import json
import random
import math
from itertools import combinations
import numpy as np
from numba import njit

SEED = [0,136,200,243,246,249,272,286,298,323,400,528,596,1056]
rng = random.Random(1000)

@njit
def seed_random():
    np.random.seed(1000)

@njit
def four_ok(a,b,c,d):
    ds = np.empty(6, np.int64)
    ds[0]=abs(a-b); ds[1]=abs(a-c); ds[2]=abs(a-d)
    ds[3]=abs(b-c); ds[4]=abs(b-d); ds[5]=abs(c-d)
    count=0
    for i in range(6):
        fresh=True
        for j in range(i):
            if ds[i]==ds[j]:
                fresh=False
                break
        if fresh:
            count+=1
    return count>=5

@njit
def add_ok(a,n,x):
    for i in range(n):
        if a[i]==x:
            return False
    for i in range(n):
        for j in range(i+1,n):
            for k in range(j+1,n):
                if not four_ok(a[i],a[j],a[k],x):
                    return False
    return True

@njit
def valid(a):
    for i in range(len(a)):
        if not add_ok(a,i,a[i]):
            return False
    return True

@njit
def popcount(x):
    n=0
    while x:
        x &= x-1
        n+=1
    return n

@njit
def branch(mask,edges,m,seen,best):
    size=popcount(mask)
    if size<=best or seen[mask]:
        return best
    seen[mask]=1
    chosen=0
    for i in range(m):
        e=edges[i]
        if mask & e == e:
            chosen=e
            break
    if chosen==0:
        return size
    # Every Sidon subset must omit at least one vertex of this collision.
    while chosen:
        bit=chosen & -chosen
        chosen-=bit
        best=branch(mask ^ bit,edges,m,seen,best)
        if best>=size-1:
            break
    return best

@njit
def exact_h(a):
    n=len(a)
    q=n*(n+1)//2
    sums=np.empty(q,np.int64)
    supports=np.empty(q,np.int64)
    t=0
    for i in range(n):
        for j in range(i,n):
            sums[t]=a[i]+a[j]
            supports[t]=(1<<i)|(1<<j)
            t+=1
    edges=np.empty(q*q//2,np.int64)
    m=0
    for i in range(q):
        for j in range(i+1,q):
            if sums[i]==sums[j]:
                e=supports[i]|supports[j]
                duplicate=False
                for k in range(m):
                    if edges[k]==e:
                        duplicate=True
                        break
                if not duplicate:
                    edges[m]=e
                    m+=1
    if m==0:
        return n,0
    # A greedy independent set supplies a rigorous lower bound.
    mask=(1<<n)-1
    while True:
        degrees=np.zeros(n,np.int64)
        bad=False
        for i in range(m):
            e=edges[i]
            if mask & e == e:
                bad=True
                for j in range(n):
                    if e & (1<<j):
                        degrees[j]+=1
        if not bad:
            break
        vertex=0
        for j in range(1,n):
            if degrees[j]>degrees[vertex]:
                vertex=j
        mask ^= 1<<vertex
    lower=popcount(mask)
    seen=np.zeros(1<<n,np.uint8)
    return branch((1<<n)-1,edges,m,seen,lower),m

@njit
def mutate(base,remove,target):
    n0=len(base)
    order=np.arange(n0)
    np.random.shuffle(order)
    remove=min(remove,n0-5)
    removed=np.empty(remove,np.int64)
    for i in range(remove):
        removed[i]=base[order[i]]
    a=np.empty(18,np.int64)
    n=0
    for i in range(remove,n0):
        a[n]=base[order[i]]
        n+=1
    forbid=np.random.random()<0.88
    noise=0.7+2.0*np.random.random()
    while n<target:
        lo=a[0]; hi=a[0]
        for i in range(n):
            lo=min(lo,a[i]); hi=max(hi,a[i])
        span=max(32,hi-lo)
        found=False
        best_score=-1.0
        best_x=0
        for trial in range(110):
            i=np.random.randint(n)
            j=np.random.randint(n-1)
            if j>=i:
                j+=1
            mode=np.random.randint(20)
            if mode<8:
                x=2*a[i]-a[j]
            elif mode<16:
                s=a[i]+a[j]
                if s%2:
                    continue
                x=s//2
            elif mode<19:
                x=a[i]+np.random.randint(-24,25)
            else:
                x=lo-span//2+np.random.randint(2*span+1)
            if abs(x)>100000000:
                continue
            banned=False
            if forbid:
                for k in range(remove):
                    if removed[k]==x:
                        banned=True
                        break
            if banned or not add_ok(a,n,x):
                continue
            count=0
            for u in range(n):
                for v in range(u+1,n):
                    if 2*x==a[u]+a[v] or 2*a[u]==x+a[v] or 2*a[v]==x+a[u]:
                        count+=1
            score=count+noise*np.random.random()
            if score>best_score:
                found=True
                best_score=score
                best_x=x
        if not found:
            break
        a[n]=best_x
        n+=1
    return a[:n].copy()


def canonical(values):
    v=sorted(int(x) for x in values)
    z=v[0]
    v=[x-z for x in v]
    g=0
    for x in v:
        g=math.gcd(g,x)
    if g>1:
        v=[x//g for x in v]
    return tuple(v)


def independent_verify(values):
    # Deliberately independent implementation matching the official checks.
    assert isinstance(values,list) and 4<=len(values)<=18
    assert all(type(x) is int and abs(x)<=1000000000 for x in values)
    assert len(set(values))==len(values)
    a=sorted(values)
    for four in combinations(a,4):
        differences={four[j]-four[i] for i in range(4) for j in range(i+1,4)}
        assert len(differences)>=5
    for size in range(len(a),0,-1):
        for subset in combinations(a,size):
            sums=set()
            good=True
            for i,left in enumerate(subset):
                for right in subset[i:]:
                    value=left+right
                    if value in sums:
                        good=False
                        break
                    sums.add(value)
                if not good:
                    break
            if good:
                return size
    raise AssertionError('No Sidon subset')

# A non-incumbent, independently checked emergency construction.
best=[0,1,2,5]
best_h=independent_verify(best)
best_edges=1
seed_key=tuple(SEED)
archive=[]
archive_keys=set()
cache={}


def consider(key):
    global best,best_h,best_edges
    if len(key)<4 or len(key)>18 or key[-1]>1000000000:
        return None
    if key in cache:
        return cache[key]
    a=np.array(key,dtype=np.int64)
    if not valid(a):
        return None
    h,e=exact_h(a)
    h=int(h); e=int(e)
    result=(h,e)
    if len(cache)>90000:
        cache.clear()
    cache[key]=result
    if key!=seed_key:
        better=h*len(best)<best_h*len(key)
        tied=h*len(best)==best_h*len(key)
        if better or (tied and (e>best_edges or (e==best_edges and key<tuple(best)))):
            best=list(key); best_h=h; best_edges=e
    if len(key)>=12 and key not in archive_keys:
        archive.append((h/len(key),-e/len(key),key,h,e))
        archive_keys.add(key)
        if len(archive)>80:
            archive.sort()
            removed=archive.pop()
            archive_keys.remove(removed[2])
    return result

seed_random()
seed_array=np.array(SEED,dtype=np.int64)
consider(seed_key)
# Compile the mutation kernel early; compilation counts against the budget.
if time.time()<DEADLINE:
    warm=mutate(seed_array,1,14)
    consider(canonical(warm))

# Systematic single-coordinate AP-biased mutations, including endpoint flips.
phase_end=min(DEADLINE, max(START+14.0,time.time()+3.0))
for removed_index in rng.sample(range(14),14):
    if time.time()>=phase_end:
        break
    base=SEED[:removed_index]+SEED[removed_index+1:]
    consider(canonical(base))
    proposals=set()
    for x,y in combinations(base,2):
        proposals.add(2*x-y)
        proposals.add(2*y-x)
        if (x+y)%2==0:
            proposals.add((x+y)//2)
    proposals=list(proposals-set(SEED))
    rng.shuffle(proposals)
    b=np.array(base,dtype=np.int64)
    for x in proposals:
        if time.time()>=phase_end:
            break
        if add_ok(b,len(b),x):
            consider(canonical(base+[x]))

current=seed_key
current_h,current_e=8,0
current_h,current_e=cache.get(seed_key,(8,12))
iterations=0
while time.time()<DEADLINE:
    r=rng.random()
    if r<0.24:
        parent=seed_key
    elif r<0.64 and archive:
        if rng.random()<0.7:
            archive.sort()
            entry=archive[rng.randrange(min(24,len(archive)))]
        else:
            entry=rng.choice(archive)
        parent=entry[2]
    else:
        parent=current
    strength=rng.choices([1,2,3,4,5,6],[32,27,19,12,7,3])[0]
    if rng.random()<0.12:
        target=rng.choice([12,13])
    else:
        target=max(14,min(18,len(parent)+rng.choice([-1,0,0,1,1,2,3])))
    proposal=mutate(np.array(parent,dtype=np.int64),strength,target)
    if time.time()>=DEADLINE:
        break
    key=canonical(proposal)
    if len(key)<10 or key==parent:
        continue
    result=consider(key)
    if result is None:
        continue
    h,e=result
    energy=h/len(key)-0.0015*e/len(key)
    old_energy=current_h/len(current)-0.0015*current_e/len(current)
    elapsed=time.time()-START
    temperature=0.006+0.016*(0.5+0.5*math.sin(elapsed*0.37))
    if energy<=old_energy or rng.random()<math.exp(min(0.0,(old_energy-energy)/temperature)):
        current=key; current_h=h; current_e=e
    iterations+=1

# This exhaustive final check is outside the search budget, with almost twenty
# seconds reserved before the overall wall-clock limit.
assert best!=SEED
verified_h=independent_verify(best)
assert verified_h==best_h
print(json.dumps({'elements':[int(x) for x in best]}))

import json
import math
import time
import numpy as np
from numba import njit

START = time.time()
SEARCH_END = START + 80.0
rng = np.random.default_rng(1001)


@njit
def seed_numba(seed):
    np.random.seed(seed)


@njit
def fwht(a):
    h = 1
    size = len(a)
    while h < size:
        for base in range(0, size, 2 * h):
            for j in range(base, base + h):
                x = a[j]
                y = a[j + h]
                a[j] = x + y
                a[j + h] = x - y
        h *= 2


@njit
def initialize(rows, offsets, size):
    counts = np.zeros(size, dtype=np.int16)
    for center in rows:
        for offset in offsets:
            counts[center ^ offset] += 1
    uncovered = 0
    for value in counts:
        if value == 0:
            uncovered += 1
    return counts, uncovered


@njit
def replace_row(rows, index, counts, offsets, spectrum, work, uncovered):
    old = rows[index]
    for offset in offsets:
        position = old ^ offset
        counts[position] -= 1
        if counts[position] == 0:
            uncovered += 1

    # Convolution with the antipodal ball gives the exact number of
    # presently uncovered vectors covered by every possible new row.
    size = len(counts)
    for j in range(size):
        work[j] = 1 if counts[j] == 0 else 0
    fwht(work)
    for j in range(size):
        work[j] *= spectrum[j]
    fwht(work)

    best_value = -1
    chosen = old
    ties = 0
    for center in range(size):
        value = work[center]
        if value > best_value:
            best_value = value
            chosen = center
            ties = 1
        elif value == best_value:
            ties += 1
            if np.random.randint(ties) == 0:
                chosen = center
    rows[index] = chosen
    for offset in offsets:
        position = chosen ^ offset
        if counts[position] == 0:
            uncovered -= 1
        counts[position] += 1
    return uncovered


@njit
def perturb(rows, counts, offsets, uncovered, amount):
    for unused in range(amount):
        index = np.random.randint(len(rows))
        old = rows[index]
        for offset in offsets:
            position = old ^ offset
            counts[position] -= 1
            if counts[position] == 0:
                uncovered += 1
        center = np.random.randint(len(counts))
        rows[index] = center
        for offset in offsets:
            position = center ^ offset
            if counts[position] == 0:
                uncovered -= 1
            counts[position] += 1
    return uncovered


@njit
def exact_discrepancy(rows, n, popcounts):
    # Signs and their complements have identical infinity norms.
    discrepancy = n
    for signs in range(1 << (n - 1)):
        worst = 0
        for row in rows:
            value = abs(n - 2 * int(popcounts[signs ^ row]))
            if value > worst:
                worst = value
        if worst < discrepancy:
            discrepancy = worst
    return discrepancy


def official_check(matrix):
    if not isinstance(matrix, list) or not 1 <= len(matrix) <= 20:
        raise ValueError('Invalid order')
    n = len(matrix)
    masks = []
    for row in matrix:
        if not isinstance(row, list) or len(row) != n:
            raise ValueError('Not square')
        mask = 0
        for j, value in enumerate(row):
            if isinstance(value, bool) or not isinstance(value, int) or value not in (-1, 1):
                raise ValueError('Invalid entry')
            if value == -1:
                mask |= 1 << j
        masks.append(mask)
    discrepancy = n
    for signs in range(1 << n):
        worst = max(abs(n - 2 * (signs ^ row).bit_count()) for row in masks)
        discrepancy = min(discrepancy, worst)
    return discrepancy


def matrix_from_rows(rows, n):
    return [[-1 if (int(row) >> j) & 1 else 1 for j in range(n)] for row in rows]


# Independently verified fallback; no incumbent matrix is used.
best_matrix = [[1 if (i & j).bit_count() % 2 == 0 else -1 for j in range(4)] for i in range(4)]
best_d = official_check(best_matrix)
best_n = 4

seed_numba(1001)
# Warm up every compiled kernel on tiny arrays. Compilation is included
# in the wall-clock budget, and the outer loop checks the absolute deadline.
tiny_rows = np.array([0, 1], dtype=np.int64)
tiny_offsets = np.array([0], dtype=np.int64)
tiny_spectrum = np.array([1, 0], dtype=np.int64)
fwht(tiny_spectrum)
tiny_counts, tiny_u = initialize(tiny_rows, tiny_offsets, 2)
tiny_work = np.empty(2, dtype=np.int64)
tiny_u = replace_row(tiny_rows, 0, tiny_counts, tiny_offsets, tiny_spectrum, tiny_work, tiny_u)
tiny_u = perturb(tiny_rows, tiny_counts, tiny_offsets, tiny_u, 1)
exact_discrepancy(tiny_rows, 2, np.array([0, 1, 1, 2], dtype=np.int16))
seed_numba(1001)

states = []
for n in (13, 15):
    if time.time() >= SEARCH_END:
        break
    size = 1 << (n - 1)
    popcounts = np.array([i.bit_count() for i in range(1 << n)], dtype=np.int16)
    radius = (n - 7) // 2
    # Representatives have final bit zero; quotient distance is
    # min(popcount(xor), n-popcount(xor)).
    offsets = np.array([i for i in range(size) if min(int(popcounts[i]), n - int(popcounts[i])) <= radius], dtype=np.int64)
    spectrum = np.zeros(size, dtype=np.int64)
    spectrum[offsets] = 1
    fwht(spectrum)
    rows = rng.choice(size, size=n, replace=False).astype(np.int64)
    counts, uncovered = initialize(rows, offsets, size)
    states.append(dict(n=n, size=size, popcounts=popcounts, offsets=offsets,
                       spectrum=spectrum, work=np.empty(size, dtype=np.int64),
                       rows=rows, counts=counts, uncovered=int(uncovered),
                       record=size + 1, local=int(uncovered), stall=0,
                       kicks=0, steps=0, done=False))


def consider(state):
    global best_matrix, best_d, best_n
    if state['uncovered'] >= state['record']:
        return
    state['record'] = state['uncovered']
    n = state['n']
    d = int(exact_discrepancy(state['rows'], n, state['popcounts']))
    if d * d * best_n > best_d * best_d * n:
        matrix = matrix_from_rows(state['rows'], n)
        # Run the literal full-cube verification before accepting a result.
        checked_d = official_check(matrix)
        if checked_d != d:
            raise RuntimeError('Discrepancy checks disagree')
        best_matrix, best_d, best_n = matrix, checked_d, n
    if state['uncovered'] == 0:
        if d < 7:
            raise RuntimeError('Coverage invariant failed')
        state['done'] = True


for state in states:
    if time.time() < SEARCH_END:
        consider(state)

while time.time() < SEARCH_END and any(not state['done'] for state in states):
    for state in states:
        if state['done'] or time.time() >= SEARCH_END:
            continue
        # Alternate short slices so neither dimension monopolizes the budget.
        slice_end = min(SEARCH_END, time.time() + 0.6)
        n = state['n']
        while time.time() < slice_end and not state['done']:
            index = int(rng.integers(n))
            state['uncovered'] = int(replace_row(
                state['rows'], index, state['counts'], state['offsets'],
                state['spectrum'], state['work'], state['uncovered']))
            state['steps'] += 1
            if state['uncovered'] < state['local']:
                state['local'] = state['uncovered']
                state['stall'] = 0
            else:
                state['stall'] += 1
            consider(state)
            if state['done']:
                break
            if state['stall'] >= 5 * n:
                state['kicks'] += 1
                if state['kicks'] >= 7 or state['steps'] >= 100 * n:
                    state['rows'] = rng.choice(state['size'], size=n, replace=False).astype(np.int64)
                    state['counts'], uncovered = initialize(state['rows'], state['offsets'], state['size'])
                    state['uncovered'] = int(uncovered)
                    state['kicks'] = 0
                    state['steps'] = 0
                else:
                    amount = 1 + state['kicks'] // 2
                    state['uncovered'] = int(perturb(state['rows'], state['counts'], state['offsets'], state['uncovered'], amount))
                state['local'] = state['uncovered']
                state['stall'] = 0

# Orders are only 4, 13, or 15, so this cannot equal the supplied incumbent.
assert len(best_matrix) != 17
assert official_check(best_matrix) == best_d
print(json.dumps({'matrix': best_matrix}))

import time
START = time.time()
import json
import math
import random
from itertools import combinations
import numpy as np
from numba import njit

SEED = 1007
random.seed(SEED)
DEADLINE = START + 80.0

@njit
def initialize():
    np.random.seed(1007)
    pop = np.zeros(1 << 18, np.uint8)
    low = np.zeros(1 << 18, np.uint8)
    for m in range(1, 1 << 18):
        pop[m] = pop[m >> 1] + (m & 1)
        if not (m & 1):
            low[m] = low[m >> 1] + 1
    return pop, low

@njit
def can_insert(a, x):
    n = len(a)
    for i in range(n):
        if a[i] == x:
            return False
    d = np.empty(6, np.int64)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                d[0] = abs(a[i] - a[j])
                d[1] = abs(a[i] - a[k])
                d[2] = abs(a[j] - a[k])
                d[3] = abs(a[i] - x)
                d[4] = abs(a[j] - x)
                d[5] = abs(a[k] - x)
                distinct = 0
                for p in range(6):
                    fresh = True
                    for q in range(p):
                        if d[p] == d[q]:
                            fresh = False
                            break
                    if fresh:
                        distinct += 1
                if distinct < 5:
                    return False
    return True

@njit
def statistics(a, pop, low):
    # In a valid (4,5)-set a four-distinct-point sum collision
    # would repeat two differences, so only AP triples remain.
    n = len(a)
    incidence = np.zeros((18, 153), np.int64)
    degree = np.zeros(18, np.int64)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (2*a[i] == a[j]+a[k] or
                    2*a[j] == a[i]+a[k] or
                    2*a[k] == a[i]+a[j]):
                    incidence[i, degree[i]] = (1 << j) | (1 << k)
                    degree[i] += 1
                    incidence[j, degree[j]] = (1 << i) | (1 << k)
                    degree[j] += 1
                    incidence[k, degree[k]] = (1 << i) | (1 << j)
                    degree[k] += 1
    good = np.zeros(1 << n, np.uint8)
    good[0] = 1
    witnesses = np.zeros(256, np.int64)
    best = 0
    count = 1
    stored = 1
    for mask in range(1, 1 << n):
        rest = mask & (mask - 1)
        if not good[rest]:
            continue
        v = low[mask]
        ok = True
        for t in range(degree[v]):
            edge = incidence[v, t]
            if rest & edge == edge:
                ok = False
                break
        if not ok:
            continue
        good[mask] = 1
        size = pop[mask]
        if size > best:
            best = size
            count = 1
            stored = 1
            witnesses[0] = mask
        elif size == best:
            count += 1
            if stored < 256:
                witnesses[stored] = mask
                stored += 1
            else:
                r = np.random.randint(count)
                if r < 256:
                    witnesses[r] = mask
    return int(best), count, witnesses, stored

@njit
def choose_point(a, witnesses, nw, extras, noise):
    n = len(a)
    candidates = np.empty(1024, np.int64)
    nc = 0
    for i in range(n):
        for j in range(i + 1, n):
            candidates[nc] = 2*a[i] - a[j]
            candidates[nc+1] = 2*a[j] - a[i]
            nc += 2
            if (a[i] + a[j]) % 2 == 0:
                candidates[nc] = (a[i] + a[j]) // 2
                nc += 1
    for x in extras:
        candidates[nc] = x
        nc += 1
    lo = np.min(a)
    hi = np.max(a)
    span = max(20, hi-lo)
    for t in range(20):
        candidates[nc] = np.random.randint(lo-span, hi+span+1)
        nc += 1
    candidates = np.unique(candidates[:nc])
    best_score = -1e30
    chosen = 0
    found = False
    edges = np.empty(153, np.int64)
    for x in candidates:
        if abs(x) > 100000000 or not can_insert(a, x):
            continue
        ne = 0
        for i in range(n):
            for j in range(i + 1, n):
                if (2*x == a[i]+a[j] or
                    2*a[i] == x+a[j] or 2*a[j] == x+a[i]):
                    edges[ne] = (1 << i) | (1 << j)
                    ne += 1
        covered = 0
        for t in range(nw):
            w = witnesses[t]
            for e in range(ne):
                if w & edges[e] == edges[e]:
                    covered += 1
                    break
        newspan = max(hi, x) - min(lo, x)
        score = covered / max(1, nw) + 0.025*ne
        score += noise * np.random.random()
        score -= 0.012 * math.log(1.0 + newspan / span)
        if score > best_score:
            best_score = score
            chosen = x
            found = True
    return found, chosen


def normalize(a):
    b = sorted(int(x) for x in a)
    b = [x-b[0] for x in b]
    g = 0
    for x in b:
        g = math.gcd(g, x)
    return np.array([x // max(g, 1) for x in b], dtype=np.int64)


def sparse_set(n):
    a = np.empty(0, dtype=np.int64)
    width = random.choice([1200, 2500, 6000])
    while len(a) < n:
        if time.time() >= DEADLINE:
            return None
        x = random.randrange(width)
        if can_insert(a, x):
            a = np.append(a, np.int64(x))
    return normalize(a)


def objective(h, count, n):
    return 18.0*h/n + 0.035*math.log1p(count)


def official_check(elements):
    if not 4 <= len(elements) <= 18:
        raise ValueError('size')
    if any(type(x) is not int or abs(x) > 1000000000 for x in elements):
        raise ValueError('integer bounds')
    if len(set(elements)) != len(elements):
        raise ValueError('duplicates')
    ordered = sorted(elements)
    for four in combinations(ordered, 4):
        differences = {four[j]-four[i] for i in range(4) for j in range(i+1, 4)}
        if len(differences) < 5:
            raise ValueError('(4,5) condition')
    for size in range(len(ordered), 0, -1):
        for subset in combinations(ordered, size):
            sums = set()
            ok = True
            for i, left in enumerate(subset):
                for right in subset[i:]:
                    s = left + right
                    if s in sums:
                        ok = False
                        break
                    sums.add(s)
                if not ok:
                    break
            if ok:
                return size
    raise ValueError('no Sidon subset')


def main():
    # A small independently valid emergency construction, not the incumbent.
    fallback = [0, 1, 3, 9]
    pop, low = initialize()
    current = sparse_set(18)
    if current is None:
        official_check(fallback)
        print(json.dumps({'elements': fallback}))
        return
    h, count, _, _ = statistics(current, pop, low)
    best = current.copy()
    best_h, best_count = h, count
    current_obj = objective(h, count, len(current))
    elites = [(current_obj, tuple(int(x) for x in current))]
    iteration = 0
    stale = 0
    while time.time() < DEADLINE:
        iteration += 1
        if stale >= 25 or iteration % 45 == 0:
            if random.random() < 0.72 and elites:
                _, coords = random.choice(elites)
                current = np.array(coords, dtype=np.int64)
            else:
                fresh = sparse_set(random.choice([17, 18, 18]))
                if fresh is None:
                    break
                current = fresh
            h, count, _, _ = statistics(current, pop, low)
            current_obj = objective(h, count, len(current))
            stale = 0
        n = len(current)
        target = n if random.random() < 0.75 else random.choice([17, 18])
        remove = random.choices([2, 3, 4, 5, 6], [1, 3, 4, 3, 1])[0]
        deleted = set(random.sample(range(n), remove))
        extras = np.array([current[i] for i in deleted], dtype=np.int64)
        partial = np.array([current[i] for i in range(n) if i not in deleted], dtype=np.int64)
        noise = random.choice([0.025, 0.08, 0.16, 0.30])
        complete = True
        while len(partial) < target:
            if time.time() >= DEADLINE:
                complete = False
                break
            ph, pc, witnesses, nw = statistics(partial, pop, low)
            found, x = choose_point(partial, witnesses, nw, extras, noise)
            if not found:
                complete = False
                break
            partial = np.append(partial, np.int64(x))
        if not complete:
            if time.time() >= DEADLINE:
                break
            stale += 1
            continue
        candidate = normalize(partial)
        ch, cc, _, _ = statistics(candidate, pop, low)
        obj = objective(ch, cc, target)
        improves = ch*len(best) < best_h*target
        ties = ch*len(best) == best_h*target
        if improves or (ties and cc < best_count):
            best = candidate.copy()
            best_h, best_count = ch, cc
            stale = 0
        else:
            stale += 1
        coords = tuple(int(x) for x in candidate)
        if len(elites) < 12 or obj < elites[-1][0]:
            if all(e[1] != coords for e in elites):
                elites.append((obj, coords))
                elites.sort()
                elites = elites[:12]
        progress = min(1.0, (time.time()-START)/80.0)
        temperature = 0.26*(1-progress) + 0.045
        if obj <= current_obj or random.random() < math.exp(min(0.0, (current_obj-obj)/temperature)):
            current = candidate
            current_obj = obj
    answer = [int(x) for x in best]
    # Independent implementation of the supplied verifier, including its
    # exhaustive maximum-Sidon-subset computation, rather than just AP tests.
    try:
        exact_h = official_check(answer)
        if exact_h != best_h:
            raise ValueError('independent Sidon check disagreed')
    except ValueError:
        answer = fallback
        official_check(answer)
    print(json.dumps({'elements': answer}))

if __name__ == '__main__':
    main()

import time
START = time.time()
import json
import math
import random
from itertools import combinations
import numpy as np
from numba import njit

rng = random.Random(1006)
RECORD = [0,136,200,243,246,249,272,286,298,323,400,528,596,1056]
DEADLINE = START + 80.0

@njit
def conflicts(a):
    n = len(a)
    degrees = np.zeros(n, np.int64)
    bad = 0
    d = np.empty(6, np.int64)
    for i in range(n-3):
        for j in range(i+1,n-2):
            for k in range(j+1,n-1):
                for l in range(k+1,n):
                    d[0] = a[j]-a[i]
                    d[1] = a[k]-a[i]
                    d[2] = a[l]-a[i]
                    d[3] = a[k]-a[j]
                    d[4] = a[l]-a[j]
                    d[5] = a[l]-a[k]
                    distinct = 0
                    for p in range(6):
                        fresh = True
                        for q in range(p):
                            if d[p] == d[q]:
                                fresh = False
                                break
                        if fresh:
                            distinct += 1
                    if distinct < 5:
                        bad += 1
                        degrees[i] += 1
                        degrees[j] += 1
                        degrees[k] += 1
                        degrees[l] += 1
    return bad, degrees

@njit
def dfs(start, selected, size, best, witness, edges, counts, n):
    if size > best:
        best = size
        witness = selected
    for v in range(start,n):
        if size + n-v <= best:
            break
        okay = True
        for j in range(counts[v]):
            e = edges[v,j]
            if (selected & e) == e:
                okay = False
                break
        if okay:
            best, witness = dfs(v+1, selected | (1 << v), size+1,
                                best, witness, edges, counts, n)
    return best, witness

@njit
def assess(a):
    n = len(a)
    bad, degree = conflicts(a)
    m = n*(n+1)//2
    sums = np.empty(m,np.int64)
    masks = np.empty(m,np.int64)
    tops = np.empty(m,np.int64)
    t = 0
    for i in range(n):
        for j in range(i,n):
            sums[t] = a[i]+a[j]
            masks[t] = (1 << i) | (1 << j)
            tops[t] = j
            t += 1
    order = np.argsort(sums)
    edges = np.empty((18,2048),np.int64)
    counts = np.zeros(18,np.int64)
    relations = 0
    p = 0
    while p < m:
        q = p+1
        while q < m and sums[order[q]] == sums[order[p]]:
            q += 1
        for x in range(p,q):
            u = order[x]
            for y in range(x+1,q):
                v = order[y]
                top = max(tops[u],tops[v])
                mask = masks[u] | masks[v]
                edges[top,counts[top]] = mask ^ (1 << top)
                counts[top] += 1
                relations += 1
        p = q
    if bad <= 2:
        h, witness = dfs(0,0,0,0,0,edges,counts,n)
    else:
        h, witness = n, (1 << n)-1
    return bad, degree, h, witness, relations

# Independent implementation of the official checks, including its exact objective.
def official_check(elements):
    assert isinstance(elements,list) and 4 <= len(elements) <= 18
    assert all(type(x) is int and abs(x) <= 10**9 for x in elements)
    assert len(set(elements)) == len(elements)
    a = sorted(elements)
    for four in combinations(a,4):
        assert len({four[j]-four[i] for i in range(4) for j in range(i+1,4)}) >= 5
    def sidon(s):
        seen = set()
        for i,x in enumerate(s):
            for y in s[i:]:
                z = x+y
                if z in seen:
                    return False
                seen.add(z)
        return True
    for k in range(len(a),0,-1):
        if any(sidon(s) for s in combinations(a,k)):
            return k
    raise AssertionError('unreachable')

best = RECORD[:-1]
best_h = official_check(best)
best_key = (best_h/len(best),-len(best),0,best[-1]-best[0])

# Trigger compilation while also obtaining a useful, non-record fallback.
def evaluate(a):
    return assess(np.array(a,dtype=np.int64))

def remember(a, result):
    global best, best_h, best_key
    bad, degree, h, witness, relations = result
    if bad or a == RECORD:
        return
    key = (int(h)/len(a),-len(a),-int(relations),a[-1]-a[0])
    if key < best_key:
        # assess exhaustively searches the sum-collision hypergraph.
        assert len(a) == len(set(a)) and all(abs(x) <= 10**9 for x in a)
        best = list(map(int,a))
        best_h = int(h)
        best_key = key

remember(best,evaluate(best))
for k in (12,13):
    for sub in combinations(RECORD,k):
        if time.time() >= DEADLINE:
            break
        a = list(sub)
        remember(a,evaluate(a))


def make_pool():
    anchors = sorted(set(RECORD + best))
    pool = set(anchors)
    # Exact midpoint/extrapolation closure supplies many possible sum relations.
    for x in anchors:
        for y in anchors:
            if (x+y) % 2 == 0:
                pool.add((x+y)//2)
            if rng.random() < 0.28:
                pool.add(2*x-y)
    # Several intersecting progressions and shifted geometric chains.
    for _ in range(24):
        x = rng.choice(anchors)
        y = rng.choice(anchors)
        gap = abs(x-y)
        if not gap:
            gap = rng.randint(1,40)
        gap = max(1,gap//rng.choice([1,2,3,4,8]))
        for j in range(-2,rng.randint(3,7)):
            pool.add(x+j*gap)
        origin = rng.choice(anchors)
        for j in range(rng.randint(3,6)):
            pool.add(origin+gap*(1 << j))
    pool = {x for x in pool if abs(x) <= 1000000}
    if len(pool) > 420:
        extra = list(pool-set(anchors))
        pool = set(anchors + rng.sample(extra,420-len(anchors)))
    return sorted(pool),pool

restart = 0
while time.time() < DEADLINE:
    pool, poolset = make_pool()
    n = [14,15,16,17,18,14,16,18][restart % 8]
    restart += 1
    a = list(RECORD if rng.random() < 0.65 else best)
    while len(a) > n:
        a.pop(rng.randrange(len(a)))
    while len(a) < n:
        x = rng.choice(pool)
        if x not in a:
            a.append(x)
    a.sort()
    result = evaluate(a)
    remember(a,result)
    temperature = rng.uniform(0.12,0.55)
    restart_end = min(DEADLINE,time.time()+rng.uniform(0.55,1.15))
    stale = 0
    for iteration in range(1200):
        if time.time() >= restart_end:
            break
        bad,degree,h,witness,relations = result
        energy = 6*int(bad)+int(h)-0.035*int(relations)
        witness_indices = [i for i in range(n) if int(witness) & (1 << i)]
        chosen = None
        chosen_result = None
        chosen_energy = float('inf')
        # Small randomized exchange neighborhood; invalid quadruples identify
        # deletions, and maximum Sidon witnesses identify useful new relations.
        for trial in range(5):
            if time.time() >= restart_end:
                break
            if bad and rng.random() < 0.9:
                weights = [int(x)+0.15 for x in degree]
                remove = rng.choices(range(n),weights=weights,k=1)[0]
            elif witness_indices and rng.random() < 0.8:
                remove = rng.choice(witness_indices)
            else:
                remove = rng.randrange(n)
            x = rng.choice(pool)
            if rng.random() < 0.65:
                w = [a[i] for i in witness_indices if i != remove]
                if len(w) >= 3:
                    u,v,z = rng.sample(w,3)
                    options = [u+v-z,2*u-v,2*v-u]
                    if (u+v) % 2 == 0:
                        options.append((u+v)//2)
                    rng.shuffle(options)
                    for q in options:
                        if q in poolset and q not in a:
                            x = q
                            break
            if x in a:
                continue
            b = a[:remove]+a[remove+1:]+[x]
            b.sort()
            r = evaluate(b)
            remember(b,r)
            e = 6*int(r[0])+int(r[2])-0.035*int(r[4])
            # Randomized ranking prevents deterministic cycling among ties.
            rank = e + rng.uniform(-0.10,0.10)
            if rank < chosen_energy:
                chosen_energy = rank
                chosen = b
                chosen_result = r
        if chosen is None:
            continue
        new_energy = 6*int(chosen_result[0])+int(chosen_result[2])-0.035*int(chosen_result[4])
        delta = new_energy-energy
        temp = temperature*(1.0+min(stale,100)/80.0)
        if delta <= 0 or rng.random() < math.exp(-min(700.0,delta/temp)):
            a,result = chosen,chosen_result
            stale = 0 if delta < -0.01 else stale+1
        else:
            stale += 1
        if stale > 170:
            break

# Reserve the remaining wall-clock margin for a completely independent check.
best = [int(x) for x in best]
assert best != RECORD
assert official_check(best) == best_h
print(json.dumps({'elements':best}))

import time
import json
import random
from itertools import combinations

import numpy as np
from numba import njit

START = time.time()
DEADLINE = START + 80.0
random.seed(1005)
B = 16384
LIMIT = 2048
RECORD = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]


@njit
def seed_rng():
    np.random.seed(1005)


@njit
def encoded(p, i):
    return p[i, 0] + B * p[i, 1]


@njit
def can_add(p, n, x, y):
    if abs(x) > LIMIT or abs(y) > LIMIT:
        return False
    v = x + B * y
    for i in range(n):
        if encoded(p, i) == v:
            return False
    d = np.empty(6, np.int64)
    for i in range(n):
        a = encoded(p, i)
        for j in range(i + 1, n):
            b = encoded(p, j)
            for k in range(j + 1, n):
                c = encoded(p, k)
                d[0] = abs(a - b)
                d[1] = abs(a - c)
                d[2] = abs(a - v)
                d[3] = abs(b - c)
                d[4] = abs(b - v)
                d[5] = abs(c - v)
                repeats = 0
                for s in range(1, 6):
                    for t in range(s):
                        if d[s] == d[t]:
                            repeats += 1
                            break
                    if repeats >= 2:
                        return False
    return True


@njit
def ap_gain(p, n, x, y):
    v = x + B * y
    result = 0
    for i in range(n):
        a = encoded(p, i)
        for j in range(i + 1, n):
            b = encoded(p, j)
            if a + b == 2 * v or a + v == 2 * b or b + v == 2 * a:
                result += 1
    return result


@njit
def popcount(x):
    result = 0
    while x:
        x &= x - 1
        result += 1
    return result


@njit
def exact_score(p, n):
    # Valid (4,5)-sets have no equal sums on four distinct points:
    # such an equality would repeat two absolute differences.
    # Thus their only Sidon obstructions are three-term APs.
    edges = np.empty(816, np.int64)
    ne = 0
    for i in range(n):
        a = encoded(p, i)
        for j in range(i + 1, n):
            b = encoded(p, j)
            for k in range(j + 1, n):
                c = encoded(p, k)
                if a + b == 2 * c or a + c == 2 * b or b + c == 2 * a:
                    edges[ne] = (1 << i) | (1 << j) | (1 << k)
                    ne += 1
    full = (1 << n) - 1
    if ne == 0:
        return n, ne
    degree = np.zeros(18, np.int64)
    mask = full
    # Greedy independent set supplies a rigorous lower bound.
    while True:
        degree[:] = 0
        active = 0
        for t in range(ne):
            e = edges[t]
            if (mask & e) == e:
                active += 1
                for i in range(n):
                    if e & (1 << i):
                        degree[i] += 1
        if active == 0:
            break
        chosen = 0
        for i in range(1, n):
            if degree[i] > degree[chosen]:
                chosen = i
        mask &= ~(1 << chosen)
    best = popcount(mask)
    seen = np.zeros(1 << n, np.uint8)
    stack = np.empty(128, np.int64)
    stack[0] = full
    sp = 1
    while sp:
        sp -= 1
        mask = stack[sp]
        count = popcount(mask)
        if count <= best or seen[mask]:
            continue
        seen[mask] = 1
        used = 0
        packing = 0
        first = 0
        degree[:] = 0
        for t in range(ne):
            e = edges[t]
            if (mask & e) == e:
                if first == 0:
                    first = e
                if not (used & e):
                    used |= e
                    packing += 1
                for i in range(n):
                    if e & (1 << i):
                        degree[i] += 1
        if first == 0:
            best = count
            continue
        if count - packing <= best:
            continue
        # Branch on a heavily constrained obstruction.
        quality = -1
        for t in range(ne):
            e = edges[t]
            if (mask & e) == e:
                q = 0
                for i in range(n):
                    if e & (1 << i):
                        q += degree[i]
                if q > quality:
                    quality = q
                    first = e
        vertices = np.empty(3, np.int64)
        nv = 0
        for i in range(n):
            if first & (1 << i):
                vertices[nv] = i
                nv += 1
        for i in range(3):
            for j in range(i + 1, 3):
                if degree[vertices[i]] > degree[vertices[j]]:
                    tmp = vertices[i]
                    vertices[i] = vertices[j]
                    vertices[j] = tmp
        for i in range(3):
            stack[sp] = mask & ~(1 << vertices[i])
            sp += 1
    return best, ne


@njit
def fill(p, n, target, samples):
    while n < target:
        bx = 0
        by = 0
        best = -1.0
        for trial in range(samples):
            if n >= 2 and np.random.random() < 0.88:
                i = np.random.randint(n)
                j = np.random.randint(n - 1)
                if j >= i:
                    j += 1
                if np.random.random() < 0.35:
                    sx = p[i, 0] + p[j, 0]
                    sy = p[i, 1] + p[j, 1]
                    if sx % 2 or sy % 2:
                        continue
                    x = sx // 2
                    y = sy // 2
                else:
                    x = 2 * p[i, 0] - p[j, 0]
                    y = 2 * p[i, 1] - p[j, 1]
            else:
                scale = 12 if np.random.random() < 0.6 else 48
                x = np.random.randint(-scale, scale + 1)
                y = np.random.randint(-scale, scale + 1)
                if n and np.random.random() < 0.5:
                    i = np.random.randint(n)
                    x += p[i, 0]
                    y += p[i, 1]
            if not can_add(p, n, x, y):
                continue
            merit = ap_gain(p, n, x, y) + 0.85 * np.random.random()
            if merit > best:
                best = merit
                bx = x
                by = y
        if best < 0:
            found = False
            for trial in range(300):
                x = np.random.randint(-512, 513)
                y = np.random.randint(-512, 513)
                if can_add(p, n, x, y):
                    bx, by = x, y
                    found = True
                    break
            if not found:
                return n
        p[n, 0] = bx
        p[n, 1] = by
        n += 1
    return n


@njit
def offspring(a, na, b, nb, target, restart):
    p = np.zeros((18, 2), np.int64)
    n = 0
    order = np.arange(na)
    np.random.shuffle(order)
    if restart:
        keep = np.random.randint(0, 5)
    else:
        drop = np.random.randint(1, 6)
        if np.random.random() < 0.13:
            drop = np.random.randint(6, 11)
        keep = min(na - drop, target - 1)
    for t in range(max(0, keep)):
        p[n] = a[order[t]]
        n += 1
    # Crossover preserves only points compatible with the inherited core.
    if np.random.random() < 0.55:
        order2 = np.arange(nb)
        np.random.shuffle(order2)
        cap = np.random.randint(n, target + 1)
        for t in range(nb):
            if n >= cap:
                break
            x, y = b[order2[t], 0], b[order2[t], 1]
            if can_add(p, n, x, y):
                p[n, 0] = x
                p[n, 1] = y
                n += 1
    n = fill(p, n, target, 46 if not restart else 72)
    return p, n


def key_of(p, n):
    return tuple(sorted(int(p[i, 0]) + B * int(p[i, 1]) for i in range(n)))


def entry(p, n):
    h, e = exact_score(p, n)
    h, e = int(h), int(e)
    return {'p': p, 'n': n, 'h': h, 'e': e,
            'rank': (h / n, -e / n), 'key': key_of(p, n)}


def official_check(values):
    assert isinstance(values, list) and 4 <= len(values) <= 18
    assert all(type(v) is int and abs(v) <= 10**9 for v in values)
    assert len(set(values)) == len(values)
    ordered = sorted(values)
    for four in combinations(ordered, 4):
        differences = {four[j] - four[i] for i in range(4) for j in range(i + 1, 4)}
        assert len(differences) >= 5
    def is_sidon(subset):
        sums = set()
        for i, left in enumerate(subset):
            for right in subset[i:]:
                value = left + right
                if value in sums:
                    return False
                sums.add(value)
        return True
    for size in range(len(ordered), 0, -1):
        for subset in combinations(ordered, size):
            if is_sidon(subset):
                return size
    raise AssertionError('No Sidon subset')


def main():
    seed_rng()
    # A genuinely planar, valid fallback, not the incumbent itself.
    base = np.zeros((18, 2), np.int64)
    base[:14, 0] = np.array(RECORD, dtype=np.int64)
    assert can_add(base, 14, 0, 1)
    base[14] = (0, 1)
    assert can_add(base, 15, 1, 3)
    base[15] = (1, 3)
    fallback = entry(base.copy(), 16)
    best = fallback
    population = [fallback]
    keys = {fallback['key']}
    iterations = 0
    while time.time() < DEADLINE:
        iterations += 1
        if len(population) < 44:
            target = random.choice((16, 17, 18))
            if len(population) < 10:
                p = np.zeros((18, 2), np.int64)
                p[:14, 0] = np.array(RECORD, dtype=np.int64)
                # Remove a few core points in some seeded individuals.
                n = 14
                if len(population) > 4:
                    indices = random.sample(range(14), 11)
                    p[:11] = p[indices].copy()
                    n = 11
                n = int(fill(p, n, target, 64))
            else:
                p, n = offspring(base, 16, base, 16, target, True)
                n = int(n)
        else:
            def tournament():
                candidates = random.sample(population, 3)
                if random.random() < 0.18:
                    return random.choice(candidates)
                return min(candidates, key=lambda z: z['rank'])
            a, b = tournament(), tournament()
            target = a['n'] if random.random() < 0.55 else random.choice((16, 17, 18))
            p, n = offspring(a['p'], a['n'], b['p'], b['n'], target,
                             random.random() < 0.08)
            n = int(n)
        if n < 16:
            continue
        key = key_of(p, n)
        if key in keys:
            continue
        candidate = entry(p, n)
        if candidate['rank'] < best['rank']:
            best = candidate
        if len(population) < 44:
            population.append(candidate)
            keys.add(key)
        else:
            # Restricted replacement allows several local basins to coexist.
            slots = random.sample(range(len(population)), 7)
            worst = max(slots, key=lambda i: population[i]['rank'])
            if candidate['rank'] <= population[worst]['rank'] or random.random() < 0.045:
                keys.remove(population[worst]['key'])
                population[worst] = candidate
                keys.add(key)
    values = list(best['key'])
    try:
        actual = official_check(values)
        assert actual == best['h']
        assert values != RECORD
    except AssertionError:
        values = list(fallback['key'])
        official_check(values)
        assert values != RECORD
    print(json.dumps({'elements': values}))


if __name__ == '__main__':
    main()

import time
START = time.time()
import json
import itertools
import random
import numpy as np
from numba import njit

SEED = 1004
rng = random.Random(SEED)
SEARCH_END = START + 78.0

@njit
def seed_random():
    np.random.seed(1004)

@njit
def valid_extension(a, depth, x):
    for i in range(depth):
        for j in range(i + 1, depth):
            for k in range(j + 1, depth):
                differences = (a[j]-a[i], a[k]-a[i], x-a[i],
                               a[k]-a[j], x-a[j], x-a[k])
                repeats = 0
                for u in range(1, 6):
                    for v in range(u):
                        if differences[u] == differences[v]:
                            repeats += 1
                            break
                    if repeats >= 2:
                        return False
    return True

@njit
def valid_set(a):
    for d in range(3, len(a)):
        if not valid_extension(a, d, a[d]):
            return False
    return True

@njit
def exact_h(a, popcount):
    # In a verified (4,5)-set, an equal-sum relation on four
    # distinct points is impossible: it repeats two differences.
    # Thus precisely the three-term APs obstruct Sidon subsets.
    n = len(a)
    edges = np.empty(300, dtype=np.int64)
    ne = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if a[i] + a[k] == 2*a[j]:
                    edges[ne] = (1 << i) | (1 << j) | (1 << k)
                    ne += 1
    good = np.zeros(1 << n, dtype=np.uint8)
    good[0] = 1
    best = 0
    for mask in range(1, 1 << n):
        bit = mask & -mask
        if not good[mask ^ bit]:
            continue
        ok = True
        for q in range(ne):
            e = edges[q]
            if e & bit and (mask & e) == e:
                ok = False
                break
        if ok:
            good[mask] = 1
            if popcount[mask] > best:
                best = popcount[mask]
    return best

@njit
def initialize_frame(a, depth, target, domain, low, width, cursor, offset):
    low[depth] = a[depth-1] + 1
    hi = domain - (target-depth-1)
    width[depth] = max(0, hi-low[depth]+1)
    cursor[depth] = 0
    if width[depth] > 0:
        offset[depth] = np.random.randint(width[depth])
    else:
        offset[depth] = 0

@njit
def advance(a, depth, target, domain, low, width, cursor, offset,
            lists, counts, maxima, popcount, best, best_h, best_n,
            attempt_limit):
    # Every row contains all Sidon subset masks of that prefix.
    pairs = np.empty(144, dtype=np.int64)
    attempts = 0
    while depth >= 1 and attempts < attempt_limit:
        if cursor[depth] >= width[depth]:
            depth -= 1
            continue
        x = low[depth] + (offset[depth] + cursor[depth]) % width[depth]
        cursor[depth] += 1
        attempts += 1
        if not valid_extension(a, depth, x):
            continue
        a[depth] = x
        level = depth + 1
        if maxima[depth] * best_n >= best_h * target:
            continue
        npairs = 0
        for i in range(depth):
            for j in range(i+1, depth):
                if a[i] + x == 2*a[j]:
                    pairs[npairs] = (1 << i) | (1 << j)
                    npairs += 1
        oldcount = counts[depth]
        for q in range(oldcount):
            lists[level, q] = lists[depth, q]
        count = oldcount
        h = maxima[depth]
        bit = 1 << depth
        hopeless = False
        for q in range(oldcount):
            mask = lists[depth, q]
            allowed = True
            for p in range(npairs):
                if (mask & pairs[p]) == pairs[p]:
                    allowed = False
                    break
            if allowed:
                lists[level, count] = mask | bit
                count += 1
                size = popcount[mask] + 1
                if size > h:
                    h = size
                    # This is already a certified lower bound for
                    # every descendant, even before finishing the row.
                    if h * best_n >= best_h * target:
                        hopeless = True
                        break
        if hopeless:
            continue
        counts[level] = count
        maxima[level] = h
        if level >= 8 and h * best_n < best_h * level:
            best_h = h
            best_n = level
            for q in range(level):
                best[q] = a[q]
        if level < target and h * best_n < best_h * target:
            depth = level
            initialize_frame(a, depth, target, domain,
                             low, width, cursor, offset)
    return depth, best_h, best_n, attempts

# Independent implementation of the official verifier, including
# equal-sum checks with repeated summands.
def verify(elements):
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        raise ValueError('size')
    if any(isinstance(x, bool) or not isinstance(x, int) or
           abs(x) > 1000000000 for x in elements):
        raise ValueError('integer range')
    if len(set(elements)) != len(elements):
        raise ValueError('duplicates')
    a = sorted(elements)
    for four in itertools.combinations(a, 4):
        differences = {four[j]-four[i]
                       for i in range(4) for j in range(i+1, 4)}
        if len(differences) < 5:
            raise ValueError('(4,5) violation')
    def sidon(s):
        sums = set()
        for i, left in enumerate(s):
            for right in s[i:]:
                value = left + right
                if value in sums:
                    return False
                sums.add(value)
        return True
    for size in range(len(a), 0, -1):
        for s in itertools.combinations(a, size):
            if sidon(s):
                return size
    raise ValueError('no Sidon subset')

# Always retain an independently verified non-record fallback.
fallback = [0, 1, 2, 5]
fallback_h = verify(fallback)
best = np.zeros(12, dtype=np.int64)
best[:4] = fallback
best_h, best_n = fallback_h, 4
popcount = np.array([i.bit_count() for i in range(4096)], dtype=np.int16)
seed_random()

# Search proper subblocks of the incumbent for an initial bound;
# the complete incumbent is never eligible for output.
record = [0, 136, 200, 243, 246, 249, 272, 286,
          298, 323, 400, 528, 596, 1056]
for n in (12, 10, 11):
    for subset in itertools.combinations(record, n):
        if time.time() >= START + 15.0:
            break
        aa = np.array(subset, dtype=np.int64)
        if not valid_set(aa):
            continue
        h = int(exact_h(aa, popcount))
        if h * best_n < best_h * n:
            best[:n] = aa
            best_h, best_n = h, n
    if time.time() >= START + 15.0:
        break

seed_solution = [int(x) for x in best[:best_n]]
seed_h = verify(seed_solution)
best_h = seed_h

# Persistent DFS arrays let the Python driver check wall time between
# small bounded batches, without relying on a timer inside numba.
a = np.zeros(12, dtype=np.int64)
low = np.zeros(13, dtype=np.int64)
width = np.zeros(13, dtype=np.int64)
cursor = np.zeros(13, dtype=np.int64)
offset = np.zeros(13, dtype=np.int64)
lists = np.zeros((13, 4096), dtype=np.int64)
counts = np.zeros(13, dtype=np.int64)
maxima = np.zeros(13, dtype=np.int64)

# Small domains sometimes finish exhaustively; larger ones receive
# randomized branch ordering and bounded restarts.
schedule = [(n, d) for d in (24, 32, 44, 60, 84, 120, 180)
            for n in (8, 9, 10, 11, 12)]
rng.shuffle(schedule)
run = 0
while time.time() < SEARCH_END:
    if run < len(schedule):
        target, domain = schedule[run]
    else:
        target = rng.choice((8, 9, 10, 10, 11, 12, 12, 12))
        domain = rng.choice((28, 36, 48, 64, 80, 104, 144, 200, 256))
    run += 1
    a[0] = 0
    lists[1, 0] = 0
    lists[1, 1] = 1
    counts[1] = 2
    maxima[1] = 1
    depth = 1
    initialize_frame(a, depth, target, domain, low, width, cursor, offset)
    used = 0
    quota = 40000 if domain < 60 else 80000
    while depth >= 1 and used < quota and time.time() < SEARCH_END:
        depth, best_h, best_n, attempts = advance(
            a, depth, target, domain, low, width, cursor, offset,
            lists, counts, maxima, popcount, best, best_h, best_n, 1500)
        used += attempts

candidate = [int(x) for x in best[:int(best_n)]]
# Final verification uses the actual verifier algorithm, not the
# AP characterization used to accelerate the search.
try:
    actual_h = verify(candidate)
    if candidate == record or actual_h * len(seed_solution) > seed_h * len(candidate):
        candidate = seed_solution
except Exception:
    candidate = seed_solution
verify(candidate)
print(json.dumps({'elements': candidate}))

import time
START = time.time()
DEADLINE = START + 79.0
import json
import random
import math
import itertools
import numpy as np
from numba import njit

rng = random.Random(1003)
RECORD = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]

@njit
def independence(n, edges):
    counts = np.zeros(n, np.int32)
    forbidden = np.zeros((n, max(1, len(edges))), np.int64)
    for e in edges:
        low = e & -e
        v = 0
        q = low
        while q > 1:
            q >>= 1
            v += 1
        forbidden[v, counts[v]] = e ^ low
        counts[v] += 1
    # dp[m] is one plus its cardinality if m is independent, otherwise zero.
    dp = np.zeros(1 << n, np.uint8)
    dp[0] = 1
    answer = 0
    for mask in range(1, 1 << n):
        low = mask & -mask
        rest = mask ^ low
        if dp[rest] == 0:
            continue
        v = 0
        q = low
        while q > 1:
            q >>= 1
            v += 1
        good = True
        for j in range(counts[v]):
            f = forbidden[v, j]
            if rest & f == f:
                good = False
                break
        if good:
            dp[mask] = dp[rest] + 1
            answer = max(answer, int(dp[mask]) - 1)
    return answer

def alpha(n, edges):
    return int(independence(n, np.array(edges, dtype=np.int64)))

def check45(a):
    if not isinstance(a, list) or not 4 <= len(a) <= 18:
        return False
    if any(type(x) is not int or abs(x) > 1000000000 for x in a):
        return False
    if len(set(a)) != len(a):
        return False
    a = sorted(a)
    for b in itertools.combinations(a, 4):
        if len({b[j] - b[i] for i in range(4) for j in range(i + 1, 4)}) < 5:
            return False
    return True

def sum_edges(a):
    seen = {}
    edges = set()
    for i, x in enumerate(a):
        for j in range(i, len(a)):
            s = x + a[j]
            mask = (1 << i) | (1 << j)
            for old in seen.get(s, ()):
                edges.add(old | mask)
            seen.setdefault(s, []).append(mask)
    return list(edges)

def is_sidon(a):
    sums = set()
    for i, x in enumerate(a):
        for y in a[i:]:
            s = x + y
            if s in sums:
                return False
            sums.add(s)
    return True

def official_h(a):
    if not check45(a):
        return None
    a = sorted(a)
    for k in range(len(a), 0, -1):
        for sub in itertools.combinations(a, k):
            if is_sidon(sub):
                return k
    return None

# An independent, verified baseline, not the submitted record.
best = RECORD + [2000003]
assert check45(best)
best_h = alpha(len(best), sum_edges(best))
fallback = best[:]
fallback_h = best_h

# Rows of B are exact integer coordinates in a rational nullspace.
# Eliminating a parameter and rescaling entire columns preserves that space.
def impose(B, equation):
    i, j, k = equation
    d = len(B[0])
    u = [B[i][c] + B[k][c] - 2 * B[j][c] for c in range(d)]
    nonzero = [c for c in range(d) if u[c]]
    if not nonzero:
        return B, False
    if d <= 2:
        return None, False
    p = min(nonzero, key=lambda c: abs(u[c]))
    up = u[p]
    cols = []
    for c in range(d):
        if c == p:
            continue
        col = [row[c] * up - row[p] * u[c] for row in B]
        g = 0
        for x in col:
            g = math.gcd(g, x)
        if g > 1:
            col = [x // g for x in col]
        cols.append(col)
    out = tuple(tuple(col[r] for col in cols) for r in range(len(B)))
    return out, True

def identity(n):
    return tuple(tuple(int(i == j) for j in range(n)) for i in range(n))

# Check the (4,5) condition for a generic linear functional on B.
# A disjoint equal-difference pair forces a forbidden parallelogram.
# Otherwise each coincidence is an AP; two APs sharing a pair are forbidden.
def structure(B):
    n = len(B)
    d = len(B[0])
    seen = {}
    used_pairs = set()
    edges = []
    degrees = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            diff = tuple(B[j][c] - B[i][c] for c in range(d))
            first = next((x for x in diff if x), 0)
            if not first:
                return None
            if first < 0:
                diff = tuple(-x for x in diff)
            pair = (1 << i) | (1 << j)
            old = seen.get(diff)
            if old is None:
                seen[diff] = pair
                continue
            if not old & pair:
                return None
            triple = old | pair
            vertices = [v for v in range(n) if triple & (1 << v)]
            if len(vertices) != 3:
                return None
            pairs = [(1 << x) | (1 << y) for x, y in itertools.combinations(vertices, 2)]
            if any(p in used_pairs for p in pairs):
                return None
            used_pairs.update(pairs)
            edges.append(triple)
            for v in vertices:
                degrees[v] += 1
    return edges, degrees, used_pairs

seed_equations = []
for j in range(14):
    for i in range(14):
        for k in range(i + 1, 14):
            if i != j and k != j and RECORD[i] + RECORD[k] == 2 * RECORD[j]:
                seed_equations.append((i, j, k))

pools = {n: [] for n in range(15, 19)}

def rebuild(n, equations):
    B = identity(n)
    independent_equations = []
    for eq in equations:
        new, changed = impose(B, eq)
        if new is None:
            return None, None
        B = new
        if changed:
            independent_equations.append(eq)
    return B, independent_equations

def realize(B, attempts=12):
    n = len(B)
    d = len(B[0])
    bound = max(sum(abs(x) for x in row) for row in B)
    cap = min(100000, 800000000 // max(1, bound))
    if cap < 1:
        return
    for attempt in range(attempts):
        if time.time() >= DEADLINE:
            return
        radius = min(cap, 101 if attempt < 5 else 10007)
        coeff = [rng.randint(-radius, radius) for _ in range(d)]
        a = [sum(x * y for x, y in zip(row, coeff)) for row in B]
        lo = min(a)
        a = [x - lo for x in a]
        g = 0
        for x in a:
            g = math.gcd(g, x)
        if g > 1:
            a = [x // g for x in a]
        center = max(a) // 2
        a = sorted(int(x - center) for x in a)
        if a != RECORD and check45(a):
            yield a

trials = 0
while time.time() < DEADLINE:
    trials += 1
    n = rng.choice([15, 16, 17, 18, 17, 18])
    pool = pools[n]
    choice = rng.random()
    if pool and choice < 0.60:
        parent = rng.choice(pool[:min(len(pool), 7)])
        equations = list(parent[3])
        rng.shuffle(equations)
        remove = rng.choice([1, 1, 2, 2, 3, 4])
        equations = equations[min(remove, len(equations)):]
    elif choice < 0.94:
        equations = seed_equations[:]
        rng.shuffle(equations)
        if rng.random() < 0.55:
            fraction = rng.uniform(0.55, 0.95)
            equations = equations[:int(len(equations) * fraction)]
    else:
        equations = []
    B, equations = rebuild(n, equations)
    if B is None:
        continue
    info = structure(B)
    if info is None:
        continue
    edges, degrees, used_pairs = info
    failures = 0
    proposals = 0
    while failures < 140 and proposals < 650 and len(B[0]) > 2:
        if time.time() >= DEADLINE:
            break
        proposals += 1
        if rng.random() < 0.72:
            minimum = min(degrees)
            low = [v for v in range(n) if degrees[v] <= minimum + (rng.random() < 0.20)]
            v = rng.choice(low)
            others = rng.sample([w for w in range(n) if w != v], 2)
            vertices = [v] + others
            rng.shuffle(vertices)
        else:
            vertices = rng.sample(range(n), 3)
        i, j, k = vertices
        if any(((1 << x) | (1 << y)) in used_pairs for x, y in itertools.combinations(vertices, 2)):
            failures += 1
            continue
        eq = (min(i, k), j, max(i, k))
        candidate_B, changed = impose(B, eq)
        if candidate_B is None or not changed:
            failures += 1
            continue
        candidate_info = structure(candidate_B)
        if candidate_info is None:
            failures += 1
            continue
        B = candidate_B
        equations.append(eq)
        edges, degrees, used_pairs = candidate_info
        failures = 0
    if time.time() >= DEADLINE:
        break
    h = alpha(n, edges)
    signature = tuple(sorted(equations))
    entry = (h, -len(edges), len(B[0]), signature)
    if not any(p[3] == signature for p in pool):
        pool.append(entry)
        pool.sort()
        del pool[16:]
    if h * len(best) > best_h * n:
        continue
    for a in realize(B):
        actual_h = alpha(n, sum_edges(a))
        comparison = actual_h * len(best) - best_h * n
        if comparison < 0 or (comparison == 0 and max(a) - min(a) < max(best) - min(best)):
            best = a
            best_h = actual_h
        # Generic realizations preserve all synthesized AP constraints.
        if actual_h == h:
            break

# Literal exhaustive verifier, independent of the synthesis and DP routines.
verified_h = official_h(best)
if verified_h is None or verified_h != best_h or best == RECORD:
    best = fallback
    assert official_h(best) == fallback_h
assert best != RECORD
print(json.dumps({'elements': [int(x) for x in best]}))

import time
START = time.time()
import json
import math
import itertools
import numpy as np
from numba import njit

N = 12
DEADLINE = START + 79.0
RECORD = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]


def verify(elements):
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        return None
    if any(isinstance(x, bool) or not isinstance(x, int) or abs(x) > 10**9 for x in elements):
        return None
    if len(set(elements)) != len(elements):
        return None
    a = sorted(elements)
    for q in itertools.combinations(a, 4):
        if len({q[j] - q[i] for i in range(4) for j in range(i + 1, 4)}) < 5:
            return None
    for k in range(len(a), 0, -1):
        for sub in itertools.combinations(a, k):
            sums = set()
            good = True
            for i, x in enumerate(sub):
                for y in sub[i:]:
                    s = x + y
                    if s in sums:
                        good = False
                        break
                    sums.add(s)
                if not good:
                    break
            if good:
                return k
    return None


# A separately verified fallback, different from the supplied 14-point record.
fallback = RECORD[:N]
fallback_h = verify(fallback)
assert fallback_h is not None


@njit
def independent(mask, size, edges, count, best):
    if size <= best:
        return best
    edge = 0
    for t in range(count):
        e = edges[t]
        if mask & e == e:
            edge = e
            break
    if edge == 0:
        return size
    while edge:
        bit = edge & -edge
        edge ^= bit
        value = independent(mask ^ bit, size - 1, edges, count, best)
        if value > best:
            best = value
        if best >= size - 1:
            break
    return best


@njit
def analyze(gaps):
    a = np.empty(N, dtype=np.int64)
    a[0] = 0
    for i in range(N - 1):
        a[i + 1] = a[i] + gaps[i]
    bad = 0
    for i in range(N - 3):
        for j in range(i + 1, N - 2):
            x = a[j] - a[i]
            for k in range(j + 1, N - 1):
                y = a[k] - a[j]
                for l in range(k + 1, N):
                    z = a[l] - a[k]
                    # For consecutive gaps x,y,z within a quadruple,
                    # these are exactly the ways to have <5 differences.
                    if x == z or (x == y and z == 2*x) or (y == z and x == 2*y):
                        bad += 1
    edges = np.empty(220, dtype=np.int64)
    count = 0
    for i in range(N - 2):
        for j in range(i + 1, N - 1):
            target = 2*a[j] - a[i]
            for k in range(j + 1, N):
                if a[k] == target:
                    edges[count] = (1 << i) | (1 << j) | (1 << k)
                    count += 1
    h = independent((1 << N) - 1, N, edges, count, 0)
    # A feasible (4,5)-set cannot contain a four-distinct-point
    # equal-sum relation: such a relation repeats two differences.
    # Thus its only Sidon obstructions are these three-term APs.
    # For infeasible states, h is merely a useful optimistic surrogate.
    energy = h + 2.25*bad - 0.025*count
    return energy, bad, h, count, a[N - 1]


@njit
def initialize_rng():
    np.random.seed(1002)


@njit
def random_gaps(scale):
    g = np.empty(N - 1, dtype=np.int64)
    for i in range(N - 1):
        g[i] = np.random.randint(1, scale + 1)
    return g


@njit
def batch(gaps, temperature, best_gaps, best_h, best_ap, best_span):
    energy, _, _, _, _ = analyze(gaps)
    for step in range(256):
        trial = gaps.copy()
        mode = np.random.randint(100)
        q = np.random.randint(N - 1)
        valid = True
        if mode < 38:
            magnitude = np.random.randint(1, 5)
            if np.random.random() < 0.18:
                magnitude *= np.random.randint(2, 9)
            if np.random.random() < 0.5:
                magnitude = -magnitude
            trial[q] += magnitude
        elif mode < 58:
            # Move an internal point while leaving the other points fixed.
            q = np.random.randint(N - 2)
            total = trial[q] + trial[q + 1]
            left = np.random.randint(1, total)
            trial[q] = left
            trial[q + 1] = total - left
        elif mode < 86:
            # Mutate one gap so that a randomly chosen triple becomes an AP.
            i = np.random.randint(N - 2)
            j = np.random.randint(i + 1, N - 1)
            k = np.random.randint(j + 1, N)
            left = 0
            right = 0
            for t in range(i, j):
                left += trial[t]
            for t in range(j, k):
                right += trial[t]
            q = np.random.randint(i, k)
            residual = right - left
            if q < j:
                trial[q] += residual
            else:
                trial[q] -= residual
        elif mode < 94:
            r = np.random.randint(N - 1)
            trial[q], trial[r] = trial[r], trial[q]
        else:
            trial[q] = np.random.randint(1, 101)
        for t in range(N - 1):
            if trial[t] < 1 or trial[t] > 800:
                valid = False
                break
        if not valid:
            continue
        e, bad, h, ap, span = analyze(trial)
        if bad == 0:
            better = h < best_h
            if h == best_h:
                better = ap > best_ap or (ap == best_ap and span < best_span)
            if better:
                best_gaps = trial.copy()
                best_h, best_ap, best_span = h, ap, span
        delta = e - energy
        if delta <= 0 or np.random.random() < math.exp(-delta / temperature):
            gaps = trial
            energy = e
    return gaps, best_gaps, best_h, best_ap, best_span


initialize_rng()
best_gaps = np.diff(np.array(fallback, dtype=np.int64))
_, bad, best_h, best_ap, best_span = analyze(best_gaps)
assert bad == 0 and best_h == fallback_h

# Examine all 12-point deletions as incumbent seeds, but begin the
# annealing trajectories from independent random compact gap sequences.
for subset in itertools.combinations(RECORD, N):
    if time.time() >= DEADLINE:
        break
    g = np.diff(np.array(subset, dtype=np.int64))
    _, bad, h, ap, span = analyze(g)
    if bad == 0 and (h, -ap, span) < (best_h, -best_ap, best_span):
        best_gaps = g.copy()
        best_h, best_ap, best_span = h, ap, span

rng = np.random.default_rng(1002)
gaps = random_gaps(30)
cycle_step = 0
cycle_length = 100
restart = 0
while time.time() < DEADLINE:
    phase = cycle_step / max(1, cycle_length - 1)
    temperature = 1.65 * (0.035 / 1.65)**phase
    gaps, best_gaps, best_h, best_ap, best_span = batch(
        gaps, temperature, best_gaps, best_h, best_ap, best_span
    )
    cycle_step += 1
    if cycle_step >= cycle_length:
        restart += 1
        cycle_step = 0
        cycle_length = int(rng.integers(55, 125))
        if restart % 3 == 0:
            gaps = best_gaps.copy()
            for _ in range(int(rng.integers(1, 4))):
                q = int(rng.integers(N - 1))
                gaps[q] = max(1, int(gaps[q]) + int(rng.integers(-12, 13)))
        else:
            gaps = random_gaps(int(rng.choice([12, 20, 30, 45, 65, 100])))

answer = [0]
for gap in best_gaps:
    answer.append(answer[-1] + int(gap))
# Independently reimplement every official check, including exhaustive
# pair-sum testing of subsets, before choosing the submitted candidate.
checked_h = verify(answer)
if checked_h is None or checked_h != int(best_h) or checked_h > fallback_h:
    answer = fallback
assert answer != RECORD
assert verify(answer) is not None
print(json.dumps({'elements': [int(x) for x in answer]}))

import time
import json
import math
from itertools import combinations
import numpy as np
from numba import njit

START = time.time()
SEARCH_DEADLINE = START + 80.0
RECORD = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]

@njit
def seed_rng():
    np.random.seed(1001)

@njit
def valid_add(a, n, x):
    for i in range(n):
        if a[i] == x:
            return False
    d = np.empty(6, dtype=np.int64)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                d[0] = abs(a[i] - a[j])
                d[1] = abs(a[i] - a[k])
                d[2] = abs(a[j] - a[k])
                d[3] = abs(a[i] - x)
                d[4] = abs(a[j] - x)
                d[5] = abs(a[k] - x)
                repeats = 0
                for u in range(1, 6):
                    for v in range(u):
                        if d[u] == d[v]:
                            repeats += 1
                            break
                    if repeats > 1:
                        return False
    return True

@njit
def greedy(limit, target, temperature, balance):
    a = np.empty(18, dtype=np.int64)
    a[0] = np.random.randint(0, limit + 1)
    n = 1
    pool = np.empty(max(1000, limit + 1), dtype=np.int64)
    marks = np.zeros(limit + 1, dtype=np.int64)
    degrees = np.empty(18, dtype=np.int64)
    stamp = 0
    while n < target:
        degrees[:] = 0
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if (a[i] + a[j] == 2*a[k] or
                        a[i] + a[k] == 2*a[j] or
                        a[j] + a[k] == 2*a[i]):
                        degrees[i] += 1
                        degrees[j] += 1
                        degrees[k] += 1
        count = 0
        if limit <= 260:
            for x in range(limit + 1):
                pool[count] = x
                count += 1
        else:
            for t in range(180):
                pool[count] = np.random.randint(0, limit + 1)
                count += 1
            for i in range(n):
                for j in range(i + 1, n):
                    x = 2*a[i] - a[j]
                    if 0 <= x <= limit:
                        pool[count] = x
                        count += 1
                    x = 2*a[j] - a[i]
                    if 0 <= x <= limit:
                        pool[count] = x
                        count += 1
                    if (a[i] + a[j]) % 2 == 0:
                        x = (a[i] + a[j]) // 2
                        pool[count] = x
                        count += 1
        np.random.shuffle(pool[:count])
        stamp += 1
        for i in range(n):
            marks[a[i]] = stamp
        best_x = -1
        best_score = -1e100
        for p in range(count):
            x = pool[p]
            if marks[x] == stamp:
                continue
            marks[x] = stamp
            score = 0.0
            for i in range(n):
                for j in range(i + 1, n):
                    if (a[i] + a[j] == 2*x or
                        a[i] + x == 2*a[j] or
                        a[j] + x == 2*a[i]):
                        score += 1.0 + balance*(1.0/(1 + degrees[i]) + 1.0/(1 + degrees[j]))
            u = max(1e-12, np.random.random())
            score -= temperature * math.log(-math.log(u))
            if score <= best_score:
                continue
            if valid_add(a, n, x):
                best_score = score
                best_x = x
        if best_x < 0:
            break
        a[n] = best_x
        n += 1
    return a[:n].copy()

@njit
def popcount(x):
    ans = 0
    while x:
        x &= x - 1
        ans += 1
    return ans

@njit
def exact_h(a):
    # A valid (4,5)-set has no equal sums on four distinct points:
    # such a relation would repeat at least two of its six differences.
    # Consequently all Sidon obstructions are three-term progressions.
    n = len(a)
    edges = np.empty(816, dtype=np.int64)
    m = 0
    degree = np.zeros(n, dtype=np.int64)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] == 2*a[k] or
                    a[i] + a[k] == 2*a[j] or
                    a[j] + a[k] == 2*a[i]):
                    edges[m] = (1 << i) | (1 << j) | (1 << k)
                    m += 1
                    degree[i] += 1
                    degree[j] += 1
                    degree[k] += 1
    if m == 0:
        return n
    # High-incidence obstructions first make the branching tree smaller.
    weight = np.empty(m, dtype=np.int64)
    for t in range(m):
        w = 0
        for i in range(n):
            if edges[t] & (1 << i):
                w += degree[i]
        weight[t] = w
    order = np.argsort(weight)
    sorted_edges = np.empty(m, dtype=np.int64)
    for t in range(m):
        sorted_edges[t] = edges[order[m - 1 - t]]
    seen = np.zeros(1 << n, dtype=np.uint8)
    stack = np.empty(3*(1 << n), dtype=np.int64)
    stack[0] = (1 << n) - 1
    top = 1
    best = 0
    while top:
        top -= 1
        mask = stack[top]
        if seen[mask]:
            continue
        seen[mask] = 1
        size = popcount(mask)
        if size <= best:
            continue
        conflict = 0
        for t in range(m):
            e = sorted_edges[t]
            if mask & e == e:
                conflict = e
                break
        if conflict == 0:
            best = size
            continue
        while conflict:
            bit = conflict & -conflict
            conflict -= bit
            child = mask ^ bit
            if not seen[child]:
                stack[top] = child
                top += 1
    return best


def valid_python(elements):
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        return False
    if any(isinstance(x, bool) or not isinstance(x, int) or abs(x) > 10**9 for x in elements):
        return False
    if len(set(elements)) != len(elements):
        return False
    ordered = sorted(elements)
    for four in combinations(ordered, 4):
        differences = {four[j] - four[i] for i in range(4) for j in range(i + 1, 4)}
        if len(differences) < 5:
            return False
    return True


def is_sidon(subset):
    sums = set()
    for i, left in enumerate(subset):
        for right in subset[i:]:
            value = left + right
            if value in sums:
                return False
            sums.add(value)
    return True


def official_h(elements):
    ordered = sorted(elements)
    for size in range(len(ordered), 0, -1):
        for subset in combinations(ordered, size):
            if is_sidon(subset):
                return size
    raise RuntimeError('No Sidon subset')


def normalize(a):
    values = sorted(int(x) for x in a)
    low = values[0]
    values = [x - low for x in values]
    g = 0
    for x in values:
        g = math.gcd(g, x)
    if g > 1:
        values = [x // g for x in values]
    return values


def main():
    best = [0, 1, 2, 5]
    assert valid_python(best)
    best_h = official_h(best)
    seed_rng()
    # Compilation is deliberately inside the wall-clock budget.
    warm = greedy(30, 5, 0.3, 0.2)
    exact_h(warm)
    rng = np.random.default_rng(1001)
    intervals = [35, 48, 64, 85, 110, 145, 190, 250, 330, 440, 600, 850, 1200, 1800, 2700]
    restarts = 0
    while time.time() < SEARCH_DEADLINE - 0.5:
        limit = int(rng.choice(intervals))
        target = int(rng.integers(10, 19))
        temperature = float(rng.choice([0.035, 0.08, 0.16, 0.3, 0.55, 0.85, 1.3]))
        balance = float(rng.uniform(0.0, 0.9))
        construction = greedy(limit, target, temperature, balance)
        restarts += 1
        for n in range(len(construction), 3, -1):
            if time.time() >= SEARCH_DEADLINE:
                break
            candidate = normalize(construction[:n])
            if candidate == RECORD:
                continue
            h = int(exact_h(np.array(candidate, dtype=np.int64)))
            better = h * len(best) < best_h * n
            tied = h * len(best) == best_h * n
            if better or (tied and (candidate[-1], n, candidate) < (best[-1], len(best), best)):
                if valid_python(candidate):
                    best = candidate
                    best_h = h
    # Independently run the literal exhaustive verifier on the retained set.
    assert best != RECORD
    assert valid_python(best)
    checked_h = official_h(best)
    assert checked_h == best_h
    print(json.dumps({'elements': [int(x) for x in best]}))

if __name__ == '__main__':
    main()

import time
START = time.time()
DEADLINE = START + 78.0
import json
import random
import math
from itertools import combinations
import numpy as np
from numba import njit

rng = random.Random(1000)
SEED = (0,136,200,243,246,249,272,286,298,323,400,528,596,1056)
LIMIT = 1000000000

@njit
def popcount(x):
    c = 0
    while x:
        x &= x - 1
        c += 1
    return c

@njit
def bit_index(x):
    i = 0
    while x > 1:
        x >>= 1
        i += 1
    return i

@njit
def independent_search(chosen, available, count, best, completion):
    if count > best:
        best = count
    while available:
        if count + popcount(available) <= best:
            break
        bit = available & -available
        available ^= bit
        v = bit_index(bit)
        permitted = available
        old = chosen
        while old:
            b = old & -old
            old ^= b
            u = bit_index(b)
            permitted &= ~completion[v, u]
        value = independent_search(chosen | bit, permitted, count + 1, best, completion)
        if value > best:
            best = value
    return best

@njit
def sidon_number(a):
    # In a (4,5)-set, a repeated sum involving four distinct
    # elements would force two repeated differences, which is forbidden.
    # Thus precisely the three-term APs obstruct Sidon subsets.
    n = len(a)
    degree = np.zeros(n, dtype=np.int64)
    edges = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if 2*a[i] == a[j]+a[k] or 2*a[j] == a[i]+a[k] or 2*a[k] == a[i]+a[j]:
                    degree[i] += 1
                    degree[j] += 1
                    degree[k] += 1
                    edges += 1
    order = np.argsort(-degree)
    b = a[order]
    completion = np.zeros((n, n), dtype=np.int64)
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if 2*b[i] == b[j]+b[k] or 2*b[j] == b[i]+b[k] or 2*b[k] == b[i]+b[j]:
                    completion[i,j] |= 1 << k
                    completion[j,i] |= 1 << k
                    completion[i,k] |= 1 << j
                    completion[k,i] |= 1 << j
                    completion[j,k] |= 1 << i
                    completion[k,j] |= 1 << i
    h = independent_search(0, (1 << n)-1, 0, 0, completion)
    return h, edges

@njit
def four_good(a, b, c, d):
    dif = np.empty(6, dtype=np.int64)
    dif[0] = abs(a-b)
    dif[1] = abs(a-c)
    dif[2] = abs(a-d)
    dif[3] = abs(b-c)
    dif[4] = abs(b-d)
    dif[5] = abs(c-d)
    distinct = 0
    for i in range(6):
        fresh = True
        for j in range(i):
            if dif[i] == dif[j]:
                fresh = False
                break
        if fresh:
            distinct += 1
    return distinct >= 5

@njit
def valid_add(a, x):
    n = len(a)
    for i in range(n):
        if a[i] == x:
            return False
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if not four_good(a[i], a[j], a[k], x):
                    return False
    return True

@njit
def legal_candidates(a, candidates):
    out = np.empty(len(candidates), dtype=np.int64)
    counts = np.empty(len(candidates), dtype=np.int64)
    used = 0
    for x in candidates:
        if abs(x) > 1000000000:
            continue
        if valid_add(a, x):
            aps = 0
            for i in range(len(a)):
                for j in range(i+1, len(a)):
                    if 2*x == a[i]+a[j] or 2*a[i] == x+a[j] or 2*a[j] == x+a[i]:
                        aps += 1
            out[used] = x
            counts[used] = aps
            used += 1
    return out[:used], counts[:used]


def official_check(elements):
    # Independent, literal implementation of the supplied verifier.
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        raise ValueError('size')
    if any(isinstance(x, bool) or not isinstance(x, int) or abs(x) > LIMIT for x in elements):
        raise ValueError('coordinate')
    if len(set(elements)) != len(elements):
        raise ValueError('duplicate')
    a = sorted(elements)
    for four in combinations(a, 4):
        ds = {four[j]-four[i] for i in range(4) for j in range(i+1,4)}
        if len(ds) < 5:
            raise ValueError('(4,5) violation')
    def is_sidon(s):
        sums = set()
        for i, x in enumerate(s):
            for y in s[i:]:
                z = x+y
                if z in sums:
                    return False
                sums.add(z)
        return True
    for size in range(len(a), 0, -1):
        for s in combinations(a, size):
            if is_sidon(s):
                return size
    raise ValueError('no Sidon subset')


def shape(a):
    a = sorted(a)
    gaps = [a[i+1]-a[i] for i in range(len(a)-1)]
    g = 0
    for d in gaps:
        g = math.gcd(g, d)
    gaps = tuple(d//g for d in gaps)
    return min(gaps, gaps[::-1])

SEED_SHAPE = shape(SEED)

def allowed_output(a):
    return len(a) != len(SEED) or shape(a) != SEED_SHAPE

# Establish an independently verified fallback before compiling search kernels.
best = tuple(SEED[:-1])
best_h = official_check(list(best))
archive = {n: [] for n in range(13,19)}
seen = set()
shape_seen = {}
iterations = 0


def register(a):
    global best, best_h
    a = tuple(sorted(int(x) for x in a))
    if a in seen or not 13 <= len(a) <= 18:
        return
    seen.add(a)
    h, edges = sidon_number(np.array(a, dtype=np.int64))
    h, edges = int(h), int(edges)
    n = len(a)
    if allowed_output(a):
        if h*len(best) < best_h*n or (h*len(best) == best_h*n and (n > len(best) or (n == len(best) and a < best))):
            best, best_h = a, h
    # Keep several structurally different neighborhoods at each size.
    sig = (n, shape(a))
    if sig in shape_seen:
        return
    shape_seen[sig] = True
    pool = archive[n]
    if pool and h > min(x[0] for x in pool) + 1:
        return
    # Perturbations preserve plateau diversity while favoring many APs.
    priority = 100*h - edges + rng.uniform(-4.0,4.0)
    pool.append((h, priority, a, edges))
    pool.sort(key=lambda x: x[1])
    if len(pool) > 36:
        del pool[36:]


def coordinate_pool(base):
    values = set()
    for i, x in enumerate(base):
        for y in base[i+1:]:
            values.add(2*x-y)
            values.add(2*y-x)
            if (x+y) % 2 == 0:
                values.add((x+y)//2)
    lo, hi = min(base), max(base)
    span = max(20, hi-lo)
    # Occasional non-AP bridge points enable subsequent replacements.
    for _ in range(16):
        values.add(rng.randint(max(-LIMIT,lo-span//2), min(LIMIT,hi+span//2)))
    values.difference_update(base)
    return np.array(sorted(x for x in values if abs(x) <= LIMIT), dtype=np.int64)

# Compilation counts against the wall-clock budget.
register(SEED)
legal_candidates(np.array(SEED[:-1], dtype=np.int64), np.array([1056,1057], dtype=np.int64))
for i in range(len(SEED)):
    if time.time() >= DEADLINE:
        break
    register(SEED[:i] + SEED[i+1:])

# First visit every one-point deletion of the incumbent as a replacement base.
initial_bases = [SEED[:i] + SEED[i+1:] for i in range(len(SEED))]
rng.shuffle(initial_bases)

while time.time() < DEADLINE:
    iterations += 1
    if initial_bases:
        base = initial_bases.pop()
    else:
        sizes = [n for n in range(13,19) if archive[n]]
        # Give larger sizes extra chances to grow and undergo replacements.
        n = rng.choice(sizes)
        pool = archive[n]
        if rng.random() < 0.72:
            entry = rng.choice(pool[:min(12,len(pool))])
        else:
            entry = rng.choice(pool)
        parent = entry[2]
        r = rng.random()
        if n < 18 and r < 0.31:
            base = parent
        elif n > 13 and r < 0.43:
            j = rng.randrange(n)
            reduced = parent[:j] + parent[j+1:]
            register(reduced)
            base = reduced
        else:
            removed = rng.randrange(n)
            base = parent[:removed] + parent[removed+1:]
            # A modest rate of two-point deletions escapes replacement traps.
            if n >= 15 and rng.random() < 0.14:
                j = rng.randrange(len(base))
                base = base[:j] + base[j+1:]
                if len(base) >= 13:
                    register(base)
    if time.time() >= DEADLINE:
        break
    candidates = coordinate_pool(base)
    legal, aps = legal_candidates(np.array(base, dtype=np.int64), candidates)
    choices = [(int(x), int(t)) for x,t in zip(legal,aps)]
    rng.shuffle(choices)
    choices.sort(key=lambda p: -p[1])
    # Evaluate all AP-rich candidates, together with a few bridge candidates.
    bridges = 0
    for x, added_aps in choices:
        if time.time() >= DEADLINE:
            break
        if added_aps == 0:
            bridges += 1
            if bridges > 5:
                continue
        register(base + (x,))
    # Rare larger kicks: delete two or three points and regrow in later rounds.
    if iterations % 23 == 0 and time.time() < DEADLINE:
        nonempty = [n for n in range(15,19) if archive[n]]
        if nonempty:
            n = rng.choice(nonempty)
            parent = rng.choice(archive[n])[2]
            keep = rng.sample(list(parent), max(13,n-rng.choice([2,3])))
            register(tuple(keep))

# Verify using all pair sums, rather than relying on the AP reduction.
answer = [int(x) for x in best]
actual_h = official_check(answer)
assert actual_h == best_h
assert allowed_output(answer)
assert tuple(sorted(answer)) != SEED
print(json.dumps({'elements': answer}))

import time
import json
import random
import itertools
import numpy as np
from numba import njit

START = time.time()
DEADLINE = START + 80.0
random.seed(1006)
BASE = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]


def verify(a):
    if not 4 <= len(a) <= 18 or len(set(a)) != len(a):
        return None
    if any(type(x) is not int or abs(x) > 1000000000 for x in a):
        return None
    a = sorted(a)
    for q in itertools.combinations(a, 4):
        if len({q[j] - q[i] for i in range(4) for j in range(i + 1, 4)}) < 5:
            return None
    for k in range(len(a), 0, -1):
        for s in itertools.combinations(a, k):
            sums = set()
            ok = True
            for i, x in enumerate(s):
                for y in s[i:]:
                    z = x + y
                    if z in sums:
                        ok = False
                        break
                    sums.add(z)
                if not ok:
                    break
            if ok:
                return k
    return None


@njit
def bad_count(a, cap):
    n = len(a)
    bad = 0
    d = np.empty(6, np.int64)
    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            for k in range(j + 1, n - 1):
                for l in range(k + 1, n):
                    d[0] = a[j] - a[i]
                    d[1] = a[k] - a[i]
                    d[2] = a[l] - a[i]
                    d[3] = a[k] - a[j]
                    d[4] = a[l] - a[j]
                    d[5] = a[l] - a[k]
                    repeats = 0
                    for u in range(6):
                        for v in range(u):
                            if d[u] == d[v]:
                                repeats += 1
                    if repeats >= 2:
                        bad += 1
                        if bad > cap:
                            return bad
    return bad


@njit
def from_gaps(g):
    a = np.zeros(len(g) + 1, np.int64)
    for i in range(len(g)):
        a[i + 1] = a[i] + g[i]
    return a


@njit
def seed_numba():
    np.random.seed(1006)


@njit
def repair(g, steps):
    g = g.copy()
    a = from_gaps(g)
    current = bad_count(a, 30)
    if current == 0 or current > 30:
        return a, current
    m = len(g)
    for step in range(steps):
        chosen = g.copy()
        best = current
        for trial in range(10):
            t = g.copy()
            p = np.random.randint(m)
            mode = np.random.randint(4)
            if mode == 0:
                delta = np.random.randint(-8, 9)
                t[p] = max(1, t[p] + delta)
            elif mode == 1 and p + 1 < m:
                total = t[p] + t[p + 1]
                v = np.random.randint(1, total)
                t[p] = v
                t[p + 1] = total - v
            elif mode == 2:
                t[p] = np.random.randint(1, max(3, min(1000, 2 * t[p] + 2)))
            else:
                t[p] = max(1, t[p] + np.random.randint(-60, 61))
            b = from_gaps(t)
            score = bad_count(b, best)
            if score < best or (score == best and np.random.random() < 0.12):
                chosen = t
                best = score
            if score == 0:
                return b, 0
        g = chosen
        current = best
    return from_gaps(g), current


# Every colliding pair of sums supplies a forbidden vertex mask.
# DP checks all subsets using forbidden masks grouped by their least vertex.
@njit
def exact_h(a, sizes, bit_index):
    n = len(a)
    p = n * (n + 1) // 2
    sums = np.empty(p, np.int64)
    masks = np.empty(p, np.int64)
    t = 0
    for i in range(n):
        for j in range(i, n):
            sums[t] = a[i] + a[j]
            masks[t] = (1 << i) | (1 << j)
            t += 1
    edges = np.zeros((18, 512), np.int64)
    counts = np.zeros(18, np.int64)
    total = 0
    covered = 0
    for i in range(p):
        for j in range(i):
            if sums[i] == sums[j]:
                e = masks[i] | masks[j]
                v = bit_index[e & -e]
                duplicate = False
                for k in range(counts[v]):
                    if edges[v, k] == e:
                        duplicate = True
                        break
                if not duplicate:
                    edges[v, counts[v]] = e
                    counts[v] += 1
                    total += 1
                    covered |= e
    limit = 1 << n
    valid = np.zeros(limit, np.uint8)
    valid[0] = 1
    answer = 0
    for mask in range(1, limit):
        bit = mask & -mask
        rest = mask ^ bit
        if valid[rest] == 0:
            continue
        v = bit_index[bit]
        good = True
        for j in range(counts[v]):
            e = edges[v, j]
            if mask & e == e:
                good = False
                break
        if good:
            valid[mask] = 1
            if sizes[mask] > answer:
                answer = sizes[mask]
    return answer, total, sizes[covered]


def normalize(a):
    a = sorted(int(x) for x in a)
    if len(set(a)) != len(a):
        return None
    offset = a[0]
    a = [x - offset for x in a]
    if a[-1] > 1000000000:
        return None
    return a


def gaps(a):
    return [a[i + 1] - a[i] for i in range(len(a) - 1)]


def tournament(pop):
    return min(random.choices(pop, k=min(3, len(pop))), key=lambda x: x[0])


def mutate(a):
    n = len(a)
    mode = random.random()
    if mode < 0.57:
        # Replacing a coordinate changes a positive gap vector after sorting.
        i, j, k = random.sample(range(n), 3)
        x, y = a[j], a[k]
        if random.random() < 0.45 and (x + y) % 2 == 0:
            value = (x + y) // 2
        else:
            value = 2 * x - y
        b = list(a)
        b[i] = value
        return normalize(b)
    g = gaps(a)
    for _ in range(1 if random.random() < 0.8 else random.randint(2, 4)):
        p = random.randrange(n - 1)
        r = random.random()
        if r < 0.42 and p + 1 < n - 1:
            total = g[p] + g[p + 1]
            v = random.randrange(1, total)
            g[p], g[p + 1] = v, total - v
        elif r < 0.8:
            g[p] = max(1, g[p] + random.choice([-32, -16, -8, -3, -2, -1, 1, 2, 3, 8, 16, 32]))
        else:
            g[p] = random.randint(1, max(2, min(1200, 2 * g[p])))
    return normalize(np.cumsum([0] + g).tolist())


def random_individual(n):
    if random.random() < 0.6:
        a = list(BASE)
        if n < len(a):
            return normalize(random.sample(a, n))
        while len(a) < n:
            x, y = random.sample(a, 2)
            value = 2 * x - y
            if value in a or random.random() < 0.35:
                value = random.randint(-500, 2600)
            if value not in a:
                a.append(value)
        return normalize(a)
    scale = random.choice([25, 50, 90, 150, 300])
    return np.cumsum([0] + [random.randint(1, scale) for _ in range(n - 1)]).tolist()


def main():
    fallback_h = verify(BASE)
    assert fallback_h == 8
    best = list(BASE)
    best_h = fallback_h
    sizes = np.zeros(1 << 18, np.uint8)
    bit_index = np.zeros(1 << 18, np.int64)
    for i in range(18):
        bit_index[1 << i] = i
        sizes[1 << i:1 << (i + 1)] = sizes[:1 << i] + 1
    seed_numba()
    # Trigger every compilation while the same wall-clock deadline is active.
    tiny = np.array([0, 1, 3, 7], dtype=np.int64)
    bad_count(tiny, 30)
    repair(np.diff(tiny), 1)
    exact_h(tiny, sizes, bit_index)
    pools = {n: [] for n in range(10, 19)}
    seen = set()
    evaluations = 0

    def consider(a, allow_repair=True):
        nonlocal best, best_h, evaluations
        if a is None or time.time() >= DEADLINE:
            return
        a = normalize(a)
        if a is None:
            return
        key = tuple(a)
        if key in seen:
            return
        arr = np.array(a, dtype=np.int64)
        violations = int(bad_count(arr, 30))
        if violations:
            if not allow_repair or violations > 30 or time.time() >= DEADLINE:
                return
            arr, violations = repair(np.diff(arr), 5 if violations < 8 else 8)
            if violations:
                return
            a = [int(x) for x in arr]
            key = tuple(a)
            if key in seen or a[-1] > 1000000000:
                return
        seen.add(key)
        if len(seen) > 90000:
            seen.clear()
        if time.time() >= DEADLINE:
            return
        h, relations, coverage = exact_h(arr, sizes, bit_index)
        h, relations, coverage = int(h), int(relations), int(coverage)
        evaluations += 1
        n = len(a)
        if h * len(best) < best_h * n:
            # Full independent verification is repeated before final output.
            best, best_h = a[:], h
        fitness = (h, -relations, -coverage)
        pop = pools[n]
        if len(pop) < 16:
            pop.append((fitness, a))
        else:
            worst = max(range(len(pop)), key=lambda i: pop[i][0])
            if fitness < pop[worst][0] or (fitness == pop[worst][0] and random.random() < 0.45):
                pop[worst] = (fitness, a)
            elif random.random() < 0.035:
                # Retain the island elite while allowing a few exploratory parents.
                elite = min(range(len(pop)), key=lambda i: pop[i][0])
                j = random.randrange(len(pop))
                if j != elite:
                    pop[j] = (fitness, a)

    consider(BASE, False)
    for n in range(10, 19):
        if time.time() >= DEADLINE:
            break
        a = BASE[:min(n, 14)]
        while len(a) < n:
            a.append(3 * a[-1] + 1)
        consider(a, False)
    iteration = 0
    while time.time() < DEADLINE:
        iteration += 1
        # All nine sizes remain active, with extra effort on record-sized blocks.
        n = random.choices(list(range(10, 19)), weights=[1, 1, 2, 1, 3, 4, 3, 3, 5])[0]
        pop = pools[n]
        if not pop or random.random() < 0.08:
            child = random_individual(n)
        else:
            parent = tournament(pop)[1]
            if len(pop) >= 2 and random.random() < 0.19:
                other = tournament(pop)[1]
                g1, g2 = gaps(parent), gaps(other)
                cut = random.randrange(1, n - 1)
                if random.random() < 0.8:
                    g = g1[:cut] + g2[cut:]
                else:
                    g = [x if random.random() < 0.5 else y for x, y in zip(g1, g2)]
                child = np.cumsum([0] + g).tolist()
                if random.random() < 0.3:
                    child = mutate(child)
            else:
                child = mutate(parent)
        consider(child)
    actual_h = verify(best)
    if actual_h is None or actual_h != best_h or actual_h * len(BASE) > fallback_h * len(best):
        best = BASE[:]
    print(json.dumps({'elements': [int(x) for x in best]}))


if __name__ == '__main__':
    main()

