@njit
def seed_random():
    np.random.seed(1005)


@njit
def prepare(v):
    n = len(v)
    forbidden = np.zeros((n, n, n), dtype=np.uint64)
    aps = np.zeros((n, n), dtype=np.uint64)
    bits = np.empty(n, dtype=np.uint64)
    for i in range(n):
        bits[i] = np.uint64(1) << np.uint64(i)
    dif = np.empty(6, dtype=np.int64)
    for a in range(n):
        for b in range(a + 1, n):
            for c in range(b + 1, n):
                if v[a] + v[c] == 2 * v[b]:
                    aps[a, b] |= bits[c]
                    aps[a, c] |= bits[b]
                    aps[b, c] |= bits[a]
                for d in range(c + 1, n):
                    dif[0] = v[b] - v[a]
                    dif[1] = v[c] - v[a]
                    dif[2] = v[d] - v[a]
                    dif[3] = v[c] - v[b]
                    dif[4] = v[d] - v[b]
                    dif[5] = v[d] - v[c]
                    distinct = 0
                    for x in range(6):
                        fresh = True
                        for y in range(x):
                            if dif[x] == dif[y]:
                                fresh = False
                                break
                        if fresh:
                            distinct += 1
                    if distinct < 5:
                        forbidden[a, b, c] |= bits[d]
                        forbidden[a, b, d] |= bits[c]
                        forbidden[a, c, d] |= bits[b]
                        forbidden[b, c, d] |= bits[a]
    return forbidden, aps, bits


@njit
def grow(s, k, forbidden, aps, bits, noise):
    n = len(bits)
    while k < 16:
        banned = np.uint64(0)
        for i in range(k):
            banned |= bits[s[i]]
            for j in range(i + 1, k):
                for l in range(j + 1, k):
                    banned |= forbidden[s[i], s[j], s[l]]
        choice = -1
        top = -1e30
        for x in range(n):
            if banned & bits[x]:
                continue
            count = 0
            for i in range(k):
                for j in range(i + 1, k):
                    if aps[s[i], s[j]] & bits[x]:
                        count += 1
            value = count + noise * np.random.random()
            if value > top:
                top = value
                choice = x
        if choice < 0:
            return False
        pos = k
        while pos > 0 and s[pos - 1] > choice:
            s[pos] = s[pos - 1]
            pos -= 1
        s[pos] = choice
        k += 1
    return True


@njit
def popcount(mask):
    answer = 0
    while mask:
        mask &= mask - 1
        answer += 1
    return answer


@njit
def independence(mask, edges, ne, memo, stamps, epoch):
    if stamps[mask] == epoch:
        return int(memo[mask])
    conflict = 0
    for i in range(ne):
        edge = edges[i]
        if mask & edge == edge:
            conflict = edge
            break
    if conflict == 0:
        answer = popcount(mask)
    else:
        answer = 0
        upper = popcount(mask) - 1
        remaining = conflict
        while remaining:
            bit = remaining & -remaining
            remaining ^= bit
            child = independence(mask ^ bit, edges, ne, memo, stamps, epoch)
            if child > answer:
                answer = child
            if answer == upper:
                break
    stamps[mask] = epoch
    memo[mask] = answer
    return answer


@njit
def measure(s, v, memo, stamps, epoch):
    # Valid (4,5)-sets have no four-distinct-element equal-sum
    # relation: such a relation would repeat two differences.
    # Thus their only Sidon obstructions are three-term APs.
    edges = np.empty(560, dtype=np.int64)
    degrees = np.zeros(16, dtype=np.int64)
    ne = 0
    for i in range(16):
        for j in range(i + 1, 16):
            for k in range(j + 1, 16):
                if v[s[i]] + v[s[k]] == 2 * v[s[j]]:
                    edges[ne] = (1 << i) | (1 << j) | (1 << k)
                    ne += 1
                    degrees[i] += 1
                    degrees[j] += 1
                    degrees[k] += 1
    # Branch on the most highly incident conflicts first.
    weights = np.empty(ne, dtype=np.int64)
    for e in range(ne):
        w = 0
        for i in range(16):
            if edges[e] & (1 << i):
                w += degrees[i]
        weights[e] = w
    for i in range(ne):
        jbest = i
        for j in range(i + 1, ne):
            if weights[j] > weights[jbest]:
                jbest = j
        temp = edges[i]
        edges[i] = edges[jbest]
        edges[jbest] = temp
        temp = weights[i]
        weights[i] = weights[jbest]
        weights[jbest] = temp
    h = independence(65535, edges, ne, memo, stamps, epoch)
    spread = 0
    for i in range(16):
        spread += degrees[i] * degrees[i]
    energy = 2.5 * h - 0.12 * ne + 0.002 * spread
    return h, energy


@njit
def batch(current, champion, v, forbidden, aps, bits,
          memo, stamps, epoch, temperature, steps):
    epoch += 1
    current_h, energy = measure(current, v, memo, stamps, epoch)
    epoch += 1
    champion_h, champion_energy = measure(champion, v, memo, stamps, epoch)
    trial = np.empty(16, dtype=np.int64)
    for iteration in range(steps):
        if np.random.random() < 0.04:
            current = champion.copy()
            current_h = champion_h
            energy = champion_energy
        u = np.random.random()
        remove = 1
        if u < 0.05:
            remove = 6
        elif u < 0.17:
            remove = 4
        elif u < 0.39:
            remove = 3
        elif u < 0.73:
            remove = 2
        dropped = 0
        count = 0
        while count < remove:
            index = np.random.randint(16)
            bit = 1 << index
            if not (dropped & bit):
                dropped |= bit
                count += 1
        k = 0
        for i in range(16):
            if not (dropped & (1 << i)):
                trial[k] = current[i]
                k += 1
        noise = 1.0 + 5.0 * np.random.random()
        if not grow(trial, k, forbidden, aps, bits, noise):
            continue
        epoch += 1
        h, e = measure(trial, v, memo, stamps, epoch)
        if h < champion_h or (h == champion_h and e < champion_energy):
            champion = trial.copy()
            champion_h = h
            champion_energy = e
        delta = e - energy
        if delta <= 0.0 or np.random.random() < math.exp(-delta / temperature):
            current = trial.copy()
            current_h = h
            energy = e
    return current, champion, champion_h, epoch


def make_pool(round_number):
    base = INCUMBENT[:]
    # Some pools include a reflected copy of the incumbent geometry.
    if round_number % 3 == 1:
        base = [1056 - x for x in base]
    bank = set()
    for a in base:
        for b in base:
            if a == b:
                continue
            bank.add(2 * a - b)
            if (a + b) % 2 == 0:
                bank.add((a + b) // 2)
            bank.add(a + b)
    for _ in range(15):
        a, b = rng.sample(base, 2)
        step = abs(a - b)
        if step % 2 == 0 and rng.random() < 0.5:
            step //= 2
        origin = rng.choice(base) - rng.randrange(3) * step
        for j in range(rng.randint(3, 5)):
            bank.add(origin + j * step)
    bank.difference_update(base)
    candidates = sorted(x for x in bank if abs(x) < 30000)
    ranked = []
    for x in candidates:
        relations = 0
        for a, b in combinations(base, 2):
            if 2 * x == a + b or 2 * a == x + b or 2 * b == x + a:
                relations += 1
        ranked.append((relations + 3.5 * rng.random(), x))
    ranked.sort(reverse=True)
    chosen = set(base)
    chosen.update(x for _, x in ranked[:20])
    rest = [x for x in candidates if x not in chosen]
    rng.shuffle(rest)
    for x in rest:
        if len(chosen) >= 52:
            break
        chosen.add(x)
    # Sparse reserve points guarantee plentiful feasible completions.
    while len(chosen) < 56:
        chosen.add(rng.randrange(1000000, 50000000))
    values = sorted(chosen)
    initial = np.empty(16, dtype=np.int64)
    for i, x in enumerate(sorted(base)):
        initial[i] = values.index(x)
    return np.array(values, dtype=np.int64), initial


seed_random()
memo = np.zeros(65536, dtype=np.int8)
stamps = np.zeros(65536, dtype=np.int64)
epoch = 0
round_number = 0
try:
    while time.time() < DEADLINE - 0.4:
        v, initial = make_pool(round_number)
        forbidden, aps, bits = prepare(v)
        if time.time() >= DEADLINE:
            break
        if not grow(initial, 14, forbidden, aps, bits, 3.0):
            round_number += 1
            continue
        current = initial.copy()
        champion = initial.copy()
        pool_start = time.time()
        pool_end = min(DEADLINE, pool_start + 2.5)
        while time.time() < pool_end:
            phase = (time.time() - pool_start) / 2.5
            temperature = 0.12 + 0.75 * (1.0 - min(1.0, phase))
            current, champion, h, epoch = batch(
                current, champion, v, forbidden, aps, bits,
                memo, stamps, epoch, temperature, 30)
            if int(h) * len(best) < best_h * 16:
                candidate = [int(v[int(i)]) for i in champion]
                checked = verify(candidate)
                if checked is not None and checked * len(best) < best_h * 16:
                    best = candidate
                    best_h = checked
            if time.time() >= DEADLINE:
                break
        round_number += 1
except Exception:
    # The independently verified incumbent remains available even if
    # a search or compilation issue occurs.
    pass

# Only independently verified candidates are ever assigned to best.
print(json.dumps({'elements': [int(x) for x in sorted(best)]}))

import time
START = time.time()
DEADLINE = START + 79.0
import json
import random
import math
from fractions import Fraction
from itertools import combinations
import numpy as np
from numba import njit

rng = random.Random(1004)
N = 17
INCUMBENT = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]


def official_check(elements):
    if not 4 <= len(elements) <= 18:
        return None
    if any(type(x) is not int or abs(x) > 10**9 for x in elements):
        return None
    if len(set(elements)) != len(elements):
        return None
    a = sorted(elements)
    for four in combinations(a, 4):
        if len({four[j] - four[i] for i in range(4) for j in range(i + 1, 4)}) < 5:
            return None
    for k in range(len(a), 0, -1):
        for sub in combinations(a, k):
            sums = set()
            good = True
            for i, x in enumerate(sub):
                for y in sub[i:]:
                    s = x + y
                    if s in sums:
                        good = False
                        break
                    sums.add(s)
                if not good:
                    break
            if good:
                return k
    return None

best = list(INCUMBENT)
best_h = official_check(best)
assert best_h == 8


@njit
def popcount(x):
    s = 0
    while x:
        x &= x - 1
        s += 1
    return s


@njit
def bit_index(x):
    k = 0
    while x > 1:
        x >>= 1
        k += 1
    return k


@njit
def independent(chosen, available, size, best_size, pairs):
    if size + popcount(available) <= best_size:
        return best_size
    if not available:
        return max(best_size, size)
    bit = available & -available
    v = bit_index(bit)
    rest = available ^ bit
    banned = 0
    old = chosen
    while old:
        b = old & -old
        old ^= b
        banned |= pairs[v, bit_index(b)]
    best_size = independent(chosen | bit, rest & ~banned, size + 1, best_size, pairs)
    if size + popcount(rest) > best_size:
        best_size = independent(chosen, rest, size, best_size, pairs)
    return best_size


@njit
def analyze(a):
    n = len(a)
    pairs = np.zeros((n, n), dtype=np.int64)
    ordered = np.sort(a)
    for i in range(n):
        if i and ordered[i] == ordered[i - 1]:
            return -1, 0, pairs
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    d = (ordered[j] - ordered[i], ordered[k] - ordered[i],
                         ordered[l] - ordered[i], ordered[k] - ordered[j],
                         ordered[l] - ordered[j], ordered[l] - ordered[k])
                    distinct = 0
                    for u in range(6):
                        new = True
                        for v in range(u):
                            if d[u] == d[v]:
                                new = False
                                break
                        if new:
                            distinct += 1
                    if distinct < 5:
                        return -1, 0, pairs
    edges = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if a[i] + a[j] == 2*a[k] or a[i] + a[k] == 2*a[j] or a[j] + a[k] == 2*a[i]:
                    pairs[i, j] |= 1 << k
                    pairs[j, i] |= 1 << k
                    pairs[i, k] |= 1 << j
                    pairs[k, i] |= 1 << j
                    pairs[j, k] |= 1 << i
                    pairs[k, j] |= 1 << i
                    edges += 1
    # A four-distinct-point sum collision would give two repeated
    # differences, so the validity test excludes it. Only APs remain.
    h = independent(0, (1 << n) - 1, 0, 0, pairs)
    return h, edges, pairs


@njit
def best_restriction(pairs, full_h):
    n = len(pairs)
    full = (1 << n) - 1
    mask, hh, nn = full, full_h, n
    for i in range(n):
        m = full ^ (1 << i)
        h = independent(0, m, 0, max(0, full_h - 1), pairs)
        if h * nn < hh * (n - 1):
            mask, hh, nn = m, h, n - 1
    for i in range(n):
        for j in range(i + 1, n):
            m = full ^ (1 << i) ^ (1 << j)
            h = independent(0, m, 0, max(0, full_h - 2), pairs)
            if h * nn < hh * (n - 2):
                mask, hh, nn = m, h, n - 2
    return mask, hh


# Compile before entering the timed search; compilation is included in START.
analyze(np.array(INCUMBENT, dtype=np.int64))
best_restriction(np.zeros((5, 5), dtype=np.int64), 5)


def primitive(row):
    g = 0
    for x in row:
        g = math.gcd(g, abs(x))
    if g > 1:
        row = [x // g for x in row]
    for x in row:
        if x:
            if x < 0:
                row = [-v for v in row]
            break
    return row


def nullspace(constraints):
    # Fraction-free exact elimination. Keep an independent subset of
    # the original AP equations, rather than synthetic echelon rows.
    pivots = {}
    independent_rows = []
    for edge in constraints:
        i, j, k = edge
        row = [0] * N
        row[i], row[j], row[k] = 1, -2, 1
        for p in range(N):
            if row[p] == 0:
                continue
            if p not in pivots:
                row = primitive(row)
                pivots[p] = row
                independent_rows.append(edge)
                break
            old = pivots[p]
            u, v = old[p], row[p]
            row = primitive([u * row[t] - v * old[t] for t in range(N)])
    free = [j for j in range(N) if j not in pivots]
    if len(free) < 2:
        return None
    basis = []
    order = sorted(pivots, reverse=True)
    for f in free:
        vec = [Fraction(0) for _ in range(N)]
        vec[f] = Fraction(1)
        for p in order:
            row = pivots[p]
            vec[p] = -sum((row[j] * vec[j] for j in range(p + 1, N)), Fraction(0)) / row[p]
        den = 1
        for x in vec:
            den = math.lcm(den, x.denominator)
        column = [int(x * den) for x in vec]
        basis.append(column)
    coords = [tuple(col[i] for col in basis) for i in range(N)]
    if len(set(coords)) != N:
        return None
    return independent_rows, coords, len(free)


def realize(constraints):
    result = nullspace(constraints)
    if result is None:
        return None
    rows, coords, dim = result
    amplitude = max(sum(abs(x) for x in row) for row in coords)
    if amplitude > 10**15:
        return None
    limit = max(2, min(10000, 400000000 // max(1, amplitude)))
    for attempt in range(2):
        coeff = [rng.randint(-limit, limit) for _ in range(dim)]
        a = [sum(x*y for x, y in zip(row, coeff)) for row in coords]
        shift = min(a)
        a = [x - shift for x in a]
        g = 0
        for x in a:
            g = math.gcd(g, x)
        if g > 1:
            a = [x // g for x in a]
        if max(a) > 2 * 10**9:
            continue
        shift = (max(a) + min(a)) // 2
        a = [int(x - shift) for x in a]
        if max(abs(x) for x in a) > 10**9:
            continue
        h, edges, pairs = analyze(np.array(a, dtype=np.int64))
        if h >= 0:
            return {'rows': rows, 'a': a, 'h': int(h), 'edges': int(edges), 'dim': dim, 'pairs': pairs}
    return None


def all_aps(a):
    out = []
    for i, j, k in combinations(range(len(a)), 3):
        if a[i] + a[k] == 2*a[j]:
            out.append((i, j, k))
        elif a[i] + a[j] == 2*a[k]:
            out.append((i, k, j))
        elif a[j] + a[k] == 2*a[i]:
            out.append((j, i, k))
    return out


seed_rows = all_aps(INCUMBENT)
seed_state = realize(seed_rows)
if seed_state is None:
    # Generic coefficients can accidentally produce extra coincidences.
    for _ in range(20):
        seed_state = realize(seed_rows)
        if seed_state is not None:
            break

pool = [] if seed_state is None else [seed_state]
signatures = set()
if seed_state is not None:
    signatures.add(tuple(sorted(seed_state['rows'])))


def quality(state):
    return (state['h'], -state['edges'], state['dim'])


def remember(state):
    sig = tuple(sorted(state['rows']))
    if sig in signatures:
        return
    signatures.add(sig)
    pool.append(state)
    if len(pool) > 48:
        # Usually remove a poor state, but occasionally protect diversity.
        choices = rng.sample(range(len(pool)), 8)
        victim = max(choices, key=lambda i: quality(pool[i]))
        old = pool.pop(victim)
        signatures.discard(tuple(sorted(old['rows'])))


def consider(state, restrictions=False):
    global best, best_h
    a, h = state['a'], state['h']
    candidate = a
    if restrictions and h <= 10 and time.time() < DEADLINE - 1.0:
        mask, hh = best_restriction(state['pairs'], h)
        candidate = [a[i] for i in range(N) if int(mask) & (1 << i)]
        h = int(hh)
    if h * len(best) < best_h * len(candidate):
        # Independently repeat the actual verifier, including exhaustive sums.
        checked = official_check(candidate)
        if checked is not None and checked * len(best) < best_h * len(candidate):
            best, best_h = sorted(candidate), checked


cycles = 0
while time.time() < DEADLINE - 0.5:
    cycles += 1
    if pool and rng.random() < 0.93:
        if rng.random() < 0.65:
            parent = min(rng.sample(pool, min(5, len(pool))), key=quality)
        else:
            parent = rng.choice(pool)
        rows = list(parent['rows'])
        # Re-express some parents using a random independent basis of all
        # actual APs; this makes deletion explore different subspaces.
        if rng.random() < 0.3:
            edges = all_aps(parent['a'])
            rng.shuffle(edges)
            ns = nullspace(edges)
            if ns is not None:
                rows = ns[0]
        drops = rng.choices([1, 2, 3, 4, 6], [35, 30, 20, 12, 3])[0]
        if rows:
            drop_indices = set(rng.sample(range(len(rows)), min(drops, len(rows))))
            rows = [r for i, r in enumerate(rows) if i not in drop_indices]
    elif rng.random() < 0.75:
        rows = list(seed_rows)
        rng.shuffle(rows)
        if rows and rng.random() < 0.5:
            rows = rows[:rng.randrange(max(1, len(rows)//2), len(rows) + 1)]
    else:
        rows = []
    current = realize(rows)
    if current is None:
        continue
    failures = 0
    trials = 0
    while failures < 65 and trials < 180 and time.time() < DEADLINE - 0.5:
        trials += 1
        ids = rng.sample(range(N), 3)
        if rng.random() < 0.35:
            ids[0] = rng.randrange(14, 17)
            if len(set(ids)) != 3:
                continue
        middle = ids[1]
        ends = sorted((ids[0], ids[2]))
        edge = (ends[0], middle, ends[1])
        if edge in current['rows']:
            continue
        proposal = realize(current['rows'] + [edge])
        if proposal is None or proposal['dim'] >= current['dim']:
            failures += 1
            continue
        current = proposal
        failures = 0
        consider(current)
    consider(current, restrictions=True)
    remember(current)

# This final exact check is comfortably outside the search budget but
# below the overall limit; only a verified plain-Python solution is printed.
if official_check(best) != best_h:
    best = list(INCUMBENT)
    assert official_check(best) == 8
print(json.dumps({'elements': [int(x) for x in best]}))

import time
import json
import math
import random
from itertools import combinations
from collections import deque
import numpy as np
from numba import njit

START = time.time()
DEADLINE = START + 80.0
rng = random.Random(1003)
BASE = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]

@njit
def legal_replacement(a, p, x):
    n = len(a)
    if x < -1000000000 or x > 1000000000:
        return False
    for i in range(n):
        if i != p and a[i] == x:
            return False
    # The old set is valid, so only quadruples containing p need checking.
    for i in range(n):
        if i == p:
            continue
        for j in range(i + 1, n):
            if j == p:
                continue
            for k in range(j + 1, n):
                if k == p:
                    continue
                ds = (abs(x-a[i]), abs(x-a[j]), abs(x-a[k]),
                      abs(a[i]-a[j]), abs(a[i]-a[k]), abs(a[j]-a[k]))
                equalities = 0
                for u in range(6):
                    for v in range(u):
                        if ds[u] == ds[v]:
                            equalities += 1
                            if equalities > 1:
                                return False
    return True

@njit
def ap_edges(a):
    n = len(a)
    edges = np.empty(n*n*n, dtype=np.int64)
    z = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if (a[i]+a[j] == 2*a[k] or a[i]+a[k] == 2*a[j]
                        or a[j]+a[k] == 2*a[i]):
                    edges[z] = (1 << i) | (1 << j) | (1 << k)
                    z += 1
    return edges[:z]

@njit
def assess(a, masks, offset, memory):
    edges = ap_edges(a)
    count = 0
    witness = 0
    m = len(masks)
    pos = offset
    for unused in range(m):
        mask = masks[pos]
        good = True
        for e in edges:
            if mask & e == e:
                good = False
                break
        if good:
            count += 1
            if witness == 0:
                witness = mask
        pos += 1
        if pos == m:
            pos = 0
    alive = 0
    for mask in memory:
        good = True
        for e in edges:
            if mask & e == e:
                good = False
                break
        if good:
            alive += 1
    return count, witness, alive

@njit
def independent_max(n, edges, offsets):
    # Exact subset DP for arbitrary repeated-sum constraints, not just APs.
    valid = np.zeros(1 << n, dtype=np.uint8)
    sizes = np.zeros(1 << n, dtype=np.uint8)
    valid[0] = 1
    best = 0
    for v in range(n):
        bit = 1 << v
        for mask in range(bit, bit << 1):
            rest = mask ^ bit
            if valid[rest] == 0:
                continue
            good = True
            for t in range(offsets[v], offsets[v+1]):
                e = edges[t]
                if mask & e == e:
                    good = False
                    break
            if good:
                valid[mask] = 1
                sizes[mask] = sizes[rest] + 1
                if sizes[mask] > best:
                    best = sizes[mask]
    return best

def verify(values):
    if not isinstance(values, list) or not 4 <= len(values) <= 18:
        return None
    if any(type(x) is not int or abs(x) > 1000000000 for x in values):
        return None
    if len(set(values)) != len(values):
        return None
    a = sorted(values)
    for q in combinations(a, 4):
        if len({q[j]-q[i] for i in range(4) for j in range(i+1, 4)}) < 5:
            return None
    sums = {}
    forbidden = set()
    for i in range(len(a)):
        for j in range(i, len(a)):
            s = a[i] + a[j]
            pair = (1 << i) | (1 << j)
            for previous in sums.get(s, ()):
                forbidden.add(previous | pair)
            sums.setdefault(s, []).append(pair)
    groups = [[] for _ in a]
    for e in forbidden:
        groups[e.bit_length()-1].append(e)
    flat = []
    offsets = [0]
    for group in groups:
        flat.extend(group)
        offsets.append(len(flat))
    return int(independent_max(len(a), np.array(flat, dtype=np.int64),
                               np.array(offsets, dtype=np.int64)))

best = BASE[:]
best_h = verify(best)
assert best_h is not None
MASKS = np.array([sum(1 << i for i in c) for c in combinations(range(18), 11)],
                 dtype=np.int64)
EMPTY = np.empty(0, dtype=np.int64)
# Compile the search kernels while the same wall-clock budget is running.
legal_replacement(np.array(BASE, dtype=np.int64), 0, 0)
assess(np.array(BASE + [1000003, 1000033, 1000037, 1000039], dtype=np.int64),
       MASKS[:1], 0, EMPTY)

def extension():
    a = BASE[:]
    while len(a) < 18 and time.time() < DEADLINE - 0.5:
        proposals = set()
        for x, y in combinations(a, 2):
            proposals.add(2*x-y)
            proposals.add(2*y-x)
            if (x+y) % 2 == 0:
                proposals.add((x+y)//2)
        proposals.difference_update(a)
        trial = list(proposals)
        rng.shuffle(trial)
        arr = np.array(a + [0], dtype=np.int64)
        p = len(a)
        choice = None
        merit = -1.0
        for t, x in enumerate(trial):
            if t % 32 == 0 and time.time() >= DEADLINE - 0.5:
                break
            if legal_replacement(arr, p, int(x)):
                arr[p] = x
                value = len(ap_edges(arr)) + rng.random()*1.8
                if value > merit:
                    merit = value
                    choice = int(x)
        if choice is None:
            for unused in range(10000):
                if time.time() >= DEADLINE - 0.5:
                    return None
                x = rng.randrange(-200000, 200001)
                if legal_replacement(arr, p, x):
                    choice = x
                    break
        if choice is None:
            return None
        a.append(choice)
    return np.array(a, dtype=np.int64) if len(a) == 18 else None

current = extension()
archive = None
archive_count = 10**9
memory = deque(maxlen=96)
tabu = {}
step = 0
stalled = 0
restart_at = time.time() + 7.0

while current is not None and time.time() < DEADLINE - 0.5:
    count, witness, _ = assess(current, MASKS, rng.randrange(len(MASKS)), EMPTY)
    count = int(count)
    witness = int(witness)
    if count < archive_count:
        archive_count = count
        archive = current.copy()
        stalled = 0
    if count == 0:
        candidate = [int(x) for x in current]
        h = verify(candidate)
        if h is not None and h*len(best) < best_h*len(candidate):
            best, best_h = candidate, h
        break
    if time.time() >= restart_at or stalled >= 32:
        if archive is not None and rng.random() < 0.45:
            current = archive.copy()
        else:
            current = extension()
        memory.clear()
        tabu.clear()
        stalled = 0
        restart_at = time.time() + 7.0
        continue

    vertices = [i for i in range(18) if witness & (1 << i)]
    # Any disjoint-pair sum collision would violate (4,5). Therefore
    # destroy the witness using a repeated summand, i.e. a 3-term AP.
    proposals = []
    for p in vertices:
        others = [i for i in vertices if i != p]
        for u, v in combinations(others, 2):
            x, y = int(current[u]), int(current[v])
            proposals.append((p, 2*x-y))
            proposals.append((p, 2*y-x))
            if (x+y) % 2 == 0:
                proposals.append((p, (x+y)//2))
    rng.shuffle(proposals)
    # Additional AP-preserving diversification moves can escape a locked witness.
    for unused in range(60):
        p, u, v = rng.sample(range(18), 3)
        x, y = int(current[u]), int(current[v])
        proposals.append((p, 2*x-y))
    mem = np.array(list(memory), dtype=np.int64)
    selected = None
    selected_merit = float('inf')
    seen = set()
    evaluated = 0
    temperature = 0.025 + min(0.20, stalled*0.008)
    for t, (p, x) in enumerate(proposals):
        if t % 8 == 0 and time.time() >= DEADLINE - 0.5:
            break
        if (p, x) in seen or x == int(current[p]):
            continue
        seen.add((p, x))
        if tabu.get((p, x), -1) > step:
            continue
        if not legal_replacement(current, p, x):
            continue
        old = int(current[p])
        current[p] = x
        c, w, alive = assess(current, MASKS, rng.randrange(len(MASKS)), mem)
        current[p] = old
        c, w = int(c), int(w)
        evaluated += 1
        if c == 0:
            selected = (p, int(x), c, w)
            break
        # Penalize resurrected old witnesses, with annealed noise for escape.
        merit = math.log1p(c) + 0.008*int(alive)
        merit += temperature * math.log(max(1e-12, rng.random()))
        if merit < selected_merit:
            selected_merit = merit
            selected = (p, int(x), c, w)
        if evaluated >= 100:
            break
    if selected is None:
        stalled += 7
        continue
    p, x, new_count, new_witness = selected
    old = int(current[p])
    tabu[(p, old)] = step + rng.randrange(8, 24)
    current[p] = x
    # Only record genuinely destroyed witnesses in the anti-recreation pool.
    destroyed = False
    for e in ap_edges(current):
        if witness & int(e) == int(e):
            destroyed = True
            break
    if destroyed:
        memory.append(witness)
    step += 1
    stalled = 0 if new_count < count else stalled + 1
    if step % 100 == 0:
        tabu = {k: v for k, v in tabu.items() if v > step}
    if new_count < archive_count:
        archive_count = new_count
        archive = current.copy()
    if new_count == 0:
        candidate = [int(x) for x in current]
        h = verify(candidate)
        if h is not None and h*len(best) < best_h*len(candidate):
            best, best_h = candidate, h
        break

# Independently repeat all domain, quadruple, and exact Sidon-size checks.
final_h = verify(best)
if final_h is None:
    best = BASE[:]
    assert verify(best) is not None
print(json.dumps({'elements': sorted(int(x) for x in best)}))

import time
START = time.time()
import json
import math
import random
from itertools import combinations
import numpy as np
from numba import njit

SEARCH_END = START + 80.0
rng = random.Random(1002)
INCUMBENT = (0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056)


def valid_set(a):
    if not 4 <= len(a) <= 18:
        return False
    if any(type(x) is not int or abs(x) > 1000000000 for x in a):
        return False
    if len(set(a)) != len(a):
        return False
    for q in combinations(sorted(a), 4):
        if len({q[j] - q[i] for i in range(4) for j in range(i + 1, 4)}) < 5:
            return False
    return True


def is_sidon(a):
    seen = set()
    for i, x in enumerate(a):
        for y in a[i:]:
            s = x + y
            if s in seen:
                return False
            seen.add(s)
    return True


def official_h(a):
    for k in range(len(a), 0, -1):
        for sub in combinations(a, k):
            if is_sidon(sub):
                return k
    raise RuntimeError('Empty construction')


@njit
def tables():
    high = np.zeros(1 << 18, dtype=np.int8)
    pop = np.zeros(1 << 18, dtype=np.int8)
    for m in range(1, 1 << 18):
        pop[m] = pop[m >> 1] + (m & 1)
        if m > 1:
            high[m] = high[m >> 1] + 1
    return high, pop


@njit
def extension_valid(a):
    n = len(a)
    x = a[n - 1]
    for i in range(n - 1):
        if a[i] == x:
            return False
    # Earlier points are already a valid construction. Check every new four-set.
    for i in range(n - 1):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n - 1):
                ds = np.empty(6, dtype=np.int64)
                ds[0] = abs(a[i] - a[j])
                ds[1] = abs(a[i] - a[k])
                ds[2] = abs(a[i] - x)
                ds[3] = abs(a[j] - a[k])
                ds[4] = abs(a[j] - x)
                ds[5] = abs(a[k] - x)
                equalities = 0
                for u in range(6):
                    for v in range(u):
                        if ds[u] == ds[v]:
                            equalities += 1
                            if equalities > 1:
                                return False
    return True


@njit
def exact_stats(a, high, pop):
    n = len(a)
    # Every sum collision becomes a forbidden vertex mask. This includes
    # diagonal sums, hence also all three-term arithmetic progressions.
    p = n * (n + 1) // 2
    sums = np.empty(p, dtype=np.int64)
    masks = np.empty(p, dtype=np.int64)
    q = 0
    for i in range(n):
        for j in range(i, n):
            sums[q] = a[i] + a[j]
            masks[q] = (1 << i) | (1 << j)
            q += 1
    edges = np.zeros((18, 512), dtype=np.int64)
    counts = np.zeros(18, dtype=np.int64)
    collisions = 0
    for i in range(p):
        for j in range(i):
            if sums[i] == sums[j]:
                mask = masks[i] | masks[j]
                top = high[mask]
                edges[top, counts[top]] = mask ^ (1 << top)
                counts[top] += 1
                collisions += 1
    good = np.zeros(1 << n, dtype=np.uint8)
    good[0] = 1
    best = 0
    ways = 1
    for mask in range(1, 1 << n):
        top = high[mask]
        rest = mask ^ (1 << top)
        if not good[rest]:
            continue
        ok = True
        for j in range(counts[top]):
            e = edges[top, j]
            if (rest & e) == e:
                ok = False
                break
        if ok:
            good[mask] = 1
            size = pop[mask]
            if size > best:
                best = size
                ways = 1
            elif size == best:
                ways += 1
    return best, collisions, ways


@njit
def assess_batch(rows, high, pop):
    out = np.full((len(rows), 3), -1, dtype=np.int64)
    for i in range(len(rows)):
        if extension_valid(rows[i]):
            h, c, w = exact_stats(rows[i], high, pop)
            out[i, 0] = h
            out[i, 1] = c
            out[i, 2] = w
    return out


def canonical(a):
    b = sorted(a)
    b = [x - b[0] for x in b]
    g = 0
    for x in b:
        g = math.gcd(g, x)
    if g > 1:
        b = [x // g for x in b]
    forward = tuple(b)
    reverse = tuple(b[-1] - x for x in reversed(b))
    return min(forward, reverse)


def proposals(a, cap):
    occupied = set(a)
    relations = set()
    for x in a:
        for y in a:
            if x != y:
                relations.add(2 * x - y)
                if (x + y) % 2 == 0:
                    relations.add((x + y) // 2)
    # General additive completions also diversify the candidate pool.
    for _ in range(70):
        x, y, z = rng.choices(a, k=3)
        relations.add(x + y - z)
    relations.difference_update(occupied)
    rel = sorted(x for x in relations if abs(x) <= 1000000000)
    rng.shuffle(rel)
    candidates = rel[:max(1, cap * 3 // 4)]
    used = set(candidates) | occupied
    span = a[-1] - a[0]
    radius = max(24, min(400, span // 2 + 12))
    small = list(range(-24, 81))
    rng.shuffle(small)
    for x in small:
        if len(candidates) >= cap:
            break
        if x not in used:
            used.add(x)
            candidates.append(x)
    for _ in range(cap):
        if len(candidates) >= cap:
            break
        x = rng.randint(a[0] - radius, a[-1] + radius)
        if x not in used and abs(x) <= 1000000000:
            used.add(x)
            candidates.append(x)
    rng.shuffle(candidates)
    return candidates


assert valid_set(INCUMBENT)
best = INCUMBENT
best_h = official_h(best)
high, pop = tables()
# Compile both kernels while charging compilation to the wall-clock budget.
assess_batch(np.array([[0, 1, 3]], dtype=np.int64), high, pop)
assert int(exact_stats(np.array(best, dtype=np.int64), high, pop)[0]) == best_h


def consider(a, h):
    global best, best_h
    if len(a) >= 4 and h * len(best) < best_h * len(a):
        # Independent complete validity check before retaining a new incumbent.
        if valid_set(a):
            best, best_h = tuple(int(x) for x in a), int(h)


def next_layer(beam, width, cap):
    pool = {}
    parents = list(beam)
    rng.shuffle(parents)
    for parent in parents:
        if time.time() >= SEARCH_END:
            break
        xs = proposals(parent, cap)
        # Small batches limit time between deadline checks, including at n=18.
        batch_size = 8 if len(parent) >= 15 else 24
        for offset in range(0, len(xs), batch_size):
            if time.time() >= SEARCH_END:
                break
            part = xs[offset:offset + batch_size]
            rows = np.array([parent + (x,) for x in part], dtype=np.int64)
            stats = assess_batch(rows, high, pop)
            for row, stat in zip(rows, stats):
                h, c, w = (int(v) for v in stat)
                if h < 0:
                    continue
                a = canonical(tuple(int(v) for v in row))
                if a in pool:
                    continue
                pool[a] = (h, c, w)
                consider(a, h)
    if not pool:
        return []
    # Exact Sidon ratio is primary (all branches have equal size). Prefer
    # collisions, using the number of maximum Sidon subsets as a tie-breaker.
    ranked = sorted(pool, key=lambda a: (pool[a][0], -pool[a][1], pool[a][2], a))
    elite_count = max(1, width // 3)
    selected = ranked[:elite_count]
    remaining = [a for a in ranked[:max(width * 6, 40)] if a not in selected]
    remaining.sort(key=lambda a: (pool[a][0] + rng.random() * 0.65,
                                  -pool[a][1] + rng.random() * 5,
                                  math.log1p(pool[a][2])))
    selected.extend(remaining[:max(0, width - len(selected))])
    return selected


restart = 0
while time.time() < SEARCH_END:
    restart += 1
    width = rng.choice([12, 16, 20])
    beam = [(0, 1)]
    for size in range(3, 13):
        if time.time() >= SEARCH_END:
            break
        beam = next_layer(beam, width, 130 if size < 9 else 200)
        if not beam:
            break
    if not beam or len(beam[0]) != 12 or time.time() >= SEARCH_END:
        continue
    # Twelve-point beams are the main search; a narrow extension phase tests
    # sizes where beating the 14-point incumbent is numerically possible.
    beam = beam[:6]
    for size in range(13, 19):
        if time.time() >= SEARCH_END:
            break
        beam = next_layer(beam, 6, 180)
        if not beam:
            break

# Re-run the literal exhaustive verifier logic, independently of the search DP.
if not valid_set(best):
    best = INCUMBENT
    best_h = 8
else:
    verified_h = official_h(best)
    if verified_h * len(INCUMBENT) > 8 * len(best):
        best = INCUMBENT
        best_h = 8
    else:
        best_h = verified_h
assert valid_set(best)
print(json.dumps({'elements': [int(x) for x in best]}))

import time
START = time.time()
import json
import math
import itertools
import numpy as np
from numba import njit

DEADLINE = START + 80.0
rng = np.random.default_rng(1001)
BASE = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]


def verify(elements):
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        return None
    if any(type(x) is not int or abs(x) > 1000000000 for x in elements):
        return None
    if len(set(elements)) != len(elements):
        return None
    a = sorted(elements)
    for q in itertools.combinations(a, 4):
        if len({q[j] - q[i] for i in range(4) for j in range(i + 1, 4)}) < 5:
            return None
    for k in range(len(a), 0, -1):
        for sub in itertools.combinations(a, k):
            sums = set()
            good = True
            for i, x in enumerate(sub):
                for y in sub[i:]:
                    s = x + y
                    if s in sums:
                        good = False
                        break
                    sums.add(s)
                if not good:
                    break
            if good:
                return k
    return None


@njit
def make_coverage(relations, targets):
    words = (len(targets) + 63) // 64
    table = np.zeros((len(relations), words), dtype=np.uint64)
    for r in range(len(relations)):
        mask = relations[r]
        for t in range(len(targets)):
            if targets[t] & mask == mask:
                table[r, t // 64] |= np.uint64(1) << np.uint64(t % 64)
    return table


@njit
def eliminate(alive, row):
    for w in range(len(alive)):
        alive[w] &= ~row[w]


@njit
def evaluate(a, lookup, coverage, initial):
    n = len(a)
    alive = initial.copy()
    relations = 0
    violations = 0
    diffs = np.empty(6, dtype=np.int64)
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if a[i] + a[k] == 2 * a[j]:
                    mask = (1 << i) | (1 << j) | (1 << k)
                    eliminate(alive, coverage[lookup[mask]])
                    relations += 1
    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            for k in range(j + 1, n - 1):
                for l in range(k + 1, n):
                    if a[i] + a[l] == a[j] + a[k]:
                        mask = (1 << i) | (1 << j) | (1 << k) | (1 << l)
                        eliminate(alive, coverage[lookup[mask]])
                        relations += 1
                    diffs[0] = a[j] - a[i]
                    diffs[1] = a[k] - a[i]
                    diffs[2] = a[l] - a[i]
                    diffs[3] = a[k] - a[j]
                    diffs[4] = a[l] - a[j]
                    diffs[5] = a[l] - a[k]
                    distinct = 0
                    for p in range(6):
                        fresh = True
                        for q in range(p):
                            if diffs[p] == diffs[q]:
                                fresh = False
                                break
                        if fresh:
                            distinct += 1
                    if distinct < 5:
                        violations += 1
    survivors = 0
    for w in range(len(alive)):
        x = alive[w]
        while x != 0:
            x &= x - np.uint64(1)
            survivors += 1
    return violations, survivors, relations


def prepare(n, k):
    targets = np.array([sum(1 << i for i in c)
                        for c in itertools.combinations(range(n), k)], dtype=np.int64)
    relations = np.array([sum(1 << i for i in c)
                          for size in (3, 4)
                          for c in itertools.combinations(range(n), size)], dtype=np.int64)
    lookup = np.full(1 << n, -1, dtype=np.int64)
    lookup[relations] = np.arange(len(relations))
    coverage = make_coverage(relations, targets)
    words = (len(targets) + 63) // 64
    initial = np.full(words, np.uint64(0xffffffffffffffff), dtype=np.uint64)
    remainder = len(targets) % 64
    if remainder:
        initial[-1] = np.uint64((1 << remainder) - 1)
    return lookup, coverage, initial


def energy(metrics, weight):
    v, s, r = metrics
    return weight * v + math.log1p(s) - 0.012 * r


def relation_value(a):
    i, j = rng.choice(len(a), 2, replace=False)
    x, y = int(a[i]), int(a[j])
    if rng.random() < 0.65:
        return 2 * x - y
    if (x + y) % 2 == 0:
        return (x + y) // 2
    return 2 * x - y


def fresh(n):
    keep = int(rng.choice([12, 13, 14], p=[0.15, 0.25, 0.60]))
    a = [int(x) for x in rng.choice(BASE, keep, replace=False)]
    if rng.random() < 0.3:
        i = int(rng.integers(len(a)))
        a[i] += int(rng.choice([-3, -2, -1, 1, 2, 3]))
    a = list(set(a))
    while len(a) < n:
        x = relation_value(a) if rng.random() < 0.9 else int(rng.integers(-300, 1600))
        if x not in a:
            a.append(x)
    a.sort()
    a = np.array(a, dtype=np.int64)
    return a - a[0]


def mutate(a, temperature):
    b = a.copy()
    i = int(rng.integers(len(b)))
    u = rng.random()
    if u < 0.76:
        # Force an arithmetic progression instead of hoping to hit an equality.
        other = np.delete(a, i)
        value = relation_value(other)
    elif u < 0.94:
        scale = int(rng.choice([1, 2, 4, 16, 64]))
        value = int(a[i]) + int(rng.integers(-scale, scale + 1))
    else:
        span = max(32, int(a[-1] - a[0]))
        value = int(rng.integers(-span // 3, span + span // 3 + 1))
    if value == int(a[i]) or value in a or abs(value) > 100000000:
        return None
    b[i] = value
    b.sort()
    b -= b[0]
    if int(b[-1]) > 1000000000:
        return None
    return b


best = list(BASE)
best_h = verify(best)
assert best_h is not None
DATA = {15: prepare(15, 9), 16: prepare(16, 10)}
# Include compilation in the wall-clock allowance.
for n in (15, 16):
    evaluate(fresh(n), *DATA[n])

elites = {15: [], 16: []}
round_number = 0
while time.time() < DEADLINE:
    n = 15 if round_number % 2 == 0 else 16
    round_number += 1
    data = DATA[n]
    weight = float(rng.uniform(1.3, 3.5))
    if elites[n] and rng.random() < 0.65:
        index = int(rng.integers(min(5, len(elites[n]))))
        current = elites[n][index][1].copy()
        for _ in range(int(rng.integers(1, 4))):
            proposal = mutate(current, 1.0)
            if proposal is not None:
                current = proposal
        metrics = evaluate(current, *data)
    else:
        current = fresh(n)
        metrics = evaluate(current, *data)
        # Select a promising perturbed-incumbent initialization.
        for _ in range(12):
            if time.time() >= DEADLINE:
                break
            trial = fresh(n)
            tm = evaluate(trial, *data)
            if energy(tm, weight) < energy(metrics, weight):
                current, metrics = trial, tm
    local_best = current.copy()
    local_metrics = metrics
    cycle_start = time.time()
    cycle_end = min(DEADLINE, cycle_start + 3.5)
    iterations = 0
    while time.time() < cycle_end:
        fraction = (time.time() - cycle_start) / 3.5
        temperature = 0.65 * (0.035 / 0.65) ** fraction
        proposal = mutate(current, temperature)
        if proposal is None:
            continue
        pm = evaluate(proposal, *data)
        iterations += 1
        if pm[0] == 0 and pm[1] == 0:
            candidate = [int(x) for x in proposal]
            h = verify(candidate)
            if h is not None and h * len(best) < best_h * len(candidate):
                best, best_h = candidate, h
        delta = energy(pm, weight) - energy(metrics, weight)
        if delta <= 0.0 or rng.random() < math.exp(-min(700.0, delta / temperature)):
            current, metrics = proposal, pm
        if energy(metrics, 2.5) < energy(local_metrics, 2.5):
            local_best, local_metrics = current.copy(), metrics
        # Brief reheating helps escape coordinate configurations with many frozen APs.
        if iterations % 1200 == 0 and rng.random() < 0.25:
            for _ in range(2):
                trial = mutate(current, 1.0)
                if trial is not None:
                    current = trial
            metrics = evaluate(current, *data)
    archive = elites[n]
    key = tuple(int(x) for x in local_best)
    if all(tuple(int(x) for x in entry[1]) != key for entry in archive):
        archive.append((energy(local_metrics, 2.5), local_best.copy()))
        archive.sort(key=lambda entry: entry[0])
        del archive[8:]

# Independent exact validation, including exhaustive computation of h(A).
checked = verify(best)
if checked is None:
    best = list(BASE)
    assert verify(best) is not None
print(json.dumps({'elements': [int(x) for x in best]}))

import time
START = time.time()
import json
import random
import math
from itertools import combinations
import numpy as np
from numba import njit

SEED = [0, 136, 200, 243, 246, 249, 272, 286, 298, 323, 400, 528, 596, 1056]
rng = random.Random(1000)
DEADLINE = START + 80.0

@njit
def four_ok(a, b, c, d):
    p = abs(a-b)
    q = abs(a-c)
    r = abs(a-d)
    s = abs(b-c)
    t = abs(b-d)
    u = abs(c-d)
    count = 1
    count += q != p
    count += r != p and r != q
    count += s != p and s != q and s != r
    count += t != p and t != q and t != r and t != s
    count += u != p and u != q and u != r and u != s and u != t
    return count >= 5

@njit
def valid(a):
    n = len(a)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    if not four_ok(a[i], a[j], a[k], a[l]):
                        return False
    return True

@njit
def proposals(a):
    n = len(a)
    buf = np.empty(n*n*n + 2*n*n, dtype=np.int64)
    z = 0
    for i in range(n):
        for j in range(n):
            buf[z] = 2*a[i]-a[j]
            z += 1
            if (a[i]+a[j]) % 2 == 0:
                buf[z] = (a[i]+a[j])//2
                z += 1
            for k in range(n):
                buf[z] = a[i]+a[j]-a[k]
                z += 1
    buf = np.sort(buf[:z])
    xs = np.empty(z, dtype=np.int64)
    gains = np.empty(z, dtype=np.int64)
    used = 0
    for pos in range(z):
        x = buf[pos]
        if pos and x == buf[pos-1]:
            continue
        if x < -1000000000 or x > 1000000000:
            continue
        exists = False
        for i in range(n):
            if a[i] == x:
                exists = True
                break
        if exists:
            continue
        good = True
        for i in range(n):
            if not good:
                break
            for j in range(i+1, n):
                if not good:
                    break
                for k in range(j+1, n):
                    if not four_ok(a[i], a[j], a[k], x):
                        good = False
                        break
        if not good:
            continue
        gain = 0
        for i in range(n):
            for j in range(i+1, n):
                if 2*x == a[i]+a[j] or 2*a[i] == a[j]+x or 2*a[j] == a[i]+x:
                    gain += 1
        xs[used] = x
        gains[used] = gain
        used += 1
    return xs[:used], gains[:used]

@njit
def branch(mask, size, edges, vertices, seen, token, best):
    if size <= best[0] or seen[mask] == token:
        return
    seen[mask] = token
    chosen = -1
    for j in range(len(edges)):
        if mask & edges[j] == edges[j]:
            chosen = j
            break
    if chosen < 0:
        best[0] = size
        return
    for k in range(3):
        branch(mask ^ vertices[chosen, k], size-1, edges, vertices, seen, token, best)
        if best[0] >= size-1:
            return

@njit
def exact_h(a, seen, token):
    # On a valid (4,5)-set, disjoint equal-sum pairs are impossible:
    # their four endpoints would have two repeated differences.
    # Thus precisely the three-term arithmetic progressions obstruct Sidonness.
    n = len(a)
    triples = np.empty((n*n*n, 3), dtype=np.int64)
    degree = np.zeros(n, dtype=np.int64)
    m = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if a[i]+a[k] == 2*a[j]:
                    triples[m, 0] = i
                    triples[m, 1] = j
                    triples[m, 2] = k
                    degree[i] += 1
                    degree[j] += 1
                    degree[k] += 1
                    m += 1
    if m == 0:
        return n, 0
    weights = np.empty(m, dtype=np.int64)
    for e in range(m):
        weights[e] = -(degree[triples[e, 0]] + degree[triples[e, 1]] + degree[triples[e, 2]])
    order = np.argsort(weights)
    edges = np.empty(m, dtype=np.int64)
    vertices = np.empty((m, 3), dtype=np.int64)
    for p in range(m):
        e = order[p]
        u, v, w = triples[e, 0], triples[e, 1], triples[e, 2]
        if degree[u] < degree[v]:
            u, v = v, u
        if degree[v] < degree[w]:
            v, w = w, v
        if degree[u] < degree[v]:
            u, v = v, u
        vertices[p, 0] = 1 << u
        vertices[p, 1] = 1 << v
        vertices[p, 2] = 1 << w
        edges[p] = (1 << u) | (1 << v) | (1 << w)
    # Greedy vertex-cover deletion supplies a lower bound for the exact search.
    mask = (1 << n)-1
    size = n
    while True:
        degree[:] = 0
        remaining = 0
        for e in range(m):
            if mask & edges[e] == edges[e]:
                remaining += 1
                for k in range(3):
                    degree[triples[order[e], k]] += 1
        if remaining == 0:
            break
        v = np.argmax(degree)
        mask ^= 1 << v
        size -= 1
    best = np.array([size], dtype=np.int64)
    branch((1 << n)-1, n, edges, vertices, seen, token, best)
    return best[0], m

def verifier(elements):
    # Independent exact implementation, including diagonal sums.
    if not isinstance(elements, list) or not 4 <= len(elements) <= 18:
        raise ValueError('size')
    if any(type(x) is not int or abs(x) > 1000000000 for x in elements):
        raise ValueError('integer bounds')
    if len(set(elements)) != len(elements):
        raise ValueError('duplicates')
    a = sorted(elements)
    for four in combinations(a, 4):
        if len({four[j]-four[i] for i in range(4) for j in range(i+1, 4)}) < 5:
            raise ValueError('(4,5) violation')
    best = 0
    chosen = []
    sums = set()
    def dfs(pos):
        nonlocal best
        if len(chosen) + len(a)-pos <= best:
            return
        if pos == len(a):
            best = max(best, len(chosen))
            return
        x = a[pos]
        new = [2*x] + [x+y for y in chosen]
        if len(set(new)) == len(new) and all(s not in sums for s in new):
            chosen.append(x)
            sums.update(new)
            dfs(pos+1)
            for s in new:
                sums.remove(s)
            chosen.pop()
        dfs(pos+1)
    dfs(0)
    return best

def canonical(values):
    a = sorted(int(x) for x in values)
    if len(set(a)) != len(a):
        return None
    origin = a[0]
    a = [x-origin for x in a]
    g = 0
    for x in a:
        g = math.gcd(g, x)
    if g > 1:
        a = [x//g for x in a]
    if a[-1] > 1000000000:
        return None
    forward = tuple(a)
    reverse = tuple(a[-1]-x for x in reversed(a))
    return min(forward, reverse)

seed_h = verifier(SEED)
best_set = tuple(SEED)
best_h = seed_h
seen = np.zeros(1 << 18, dtype=np.int64)
token = 0
archives = {n: [] for n in range(11, 19)}
visited = set()

# Trigger all substantial JIT compilation while charging it to the budget.
a0 = np.array(sorted(SEED), dtype=np.int64)
valid(a0)
proposals(a0)
exact_h(a0, seen, 1)
token = 1

def consider(values):
    global token, best_set, best_h
    if time.time() >= DEADLINE:
        return
    key = canonical(values)
    if key is None or key in visited or not 11 <= len(key) <= 18:
        return
    visited.add(key)
    a = np.array(key, dtype=np.int64)
    if not valid(a):
        return
    token += 1
    h, edges = exact_h(a, seen, token)
    h, edges = int(h), int(edges)
    if h*len(best_set) < best_h*len(key):
        best_set, best_h = key, h
    # Randomized secondary ranking retains structurally diverse near-ties.
    rank = (h, -edges + 4.0*rng.random())
    bucket = archives[len(key)]
    bucket.append((rank, key, edges))
    bucket.sort(key=lambda entry: entry[0])
    if len(bucket) > 32:
        bucket.pop()

consider(SEED)
iteration = 0
while time.time() < DEADLINE and any(archives.values()):
    iteration += 1
    available = [n for n, entries in archives.items() if entries]
    weights = [1.0 if n < 14 else 2.5 for n in available]
    n = rng.choices(available, weights=weights, k=1)[0]
    bucket = archives[n]
    if rng.random() < 0.3:
        parent = rng.choice(bucket[:min(6, len(bucket))])[1]
    else:
        parent = rng.choice(bucket)[1]
    extend = n < 18 and (n == 11 or rng.random() < 0.68)
