        indices = list(range(len(xs)))
        priorities = [(int(gains[i]) + rng.random(), i) for i in indices]
        priorities.sort(reverse=True)
        limit = 48 if iteration % 9 == 0 else 24
        take = [i for _, i in priorities[:limit//2]]
        used = set(take)
        rest = [i for i in indices if i not in used]
        rng.shuffle(rest)
        take.extend(rest[:limit-len(take)])
        for i in take:
